window.MED_COMPENDIUM = {"asOf":"2026-10-31","disclaimer":"Educational revision only; unreviewed by clinicians. Verify the underlying reference, current national guidance, population and hospital protocol before making patient care decisions. No patient-identifying data should be entered.","sources":{"Anatomy":{"name":"OpenStax Anatomy and Physiology 2e","url":"https://openstax.org/details/books/anatomy-and-physiology-2e","scope":"Further reading index; does not confirm every individual statement"},"Physiology":{"name":"OpenStax Anatomy and Physiology 2e","url":"https://openstax.org/details/books/anatomy-and-physiology-2e","scope":"Further reading index; does not confirm every individual statement"},"Pathology":{"name":"MSD Manual Professional — Health Topics","url":"https://www.msdmanuals.com/professional/health-topics","scope":"Further reading index; does not confirm every individual statement"},"Microbiology & Immunology":{"name":"OpenStax Microbiology","url":"https://openstax.org/details/books/microbiology","scope":"Further reading index; does not confirm every individual statement"},"Pharmacology":{"name":"WHO Model Essential Medicines List, 2025","url":"https://www.who.int/groups/expert-committee-on-selection-and-use-of-essential-medicines/essential-medicines-lists/","scope":"Further reading index; does not confirm every individual statement"},"Diagnostics & Interpretation":{"name":"MedlinePlus — Medical Tests","url":"https://medlineplus.gov/lab-tests/","scope":"Further reading index; does not confirm every individual statement"},"Clinical Medicine":{"name":"MSD Manual Professional — Health Topics","url":"https://www.msdmanuals.com/professional/health-topics","scope":"Further reading index; does not confirm every individual statement"},"Clinical Skills & Procedures":{"name":"Stanford Medicine 25 — Bedside Examination","url":"https://stanfordmedicine25.stanford.edu/the25.html","scope":"Further reading index; does not confirm every individual statement"},"Emergency & Critical Care":{"name":"Resuscitation Council UK — ABCDE","url":"https://www.resus.org.uk/library/abcde-approach","scope":"Further reading index; does not confirm every individual statement"},"Ethics, Safety & Public Health":{"name":"WHO — Global Patient Safety Action Plan","url":"https://www.who.int/publications/i/item/9789240032705","scope":"Further reading index; does not confirm every individual statement"}},"entries":[{"id":"mc-0001","title":"Anatomical position","category":"Anatomy","level":"Foundation","fact":"The reference posture is standing upright with palms facing forward; left and right are the subject's sides.","source":"Anatomy"},{"id":"mc-0002","title":"Sagittal plane","category":"Anatomy","level":"Foundation","fact":"A sagittal section separates left from right; the midsagittal plane divides the body into equal halves.","source":"Anatomy"},{"id":"mc-0003","title":"Coronal plane","category":"Anatomy","level":"Foundation","fact":"A coronal section separates anterior from posterior regions.","source":"Anatomy"},{"id":"mc-0004","title":"Transverse plane","category":"Anatomy","level":"Foundation","fact":"A transverse section separates superior and inferior portions.","source":"Anatomy"},{"id":"mc-0005","title":"Proximal versus distal","category":"Anatomy","level":"Foundation","fact":"Proximal indicates closer to a limb's origin; distal indicates farther from it.","source":"Anatomy"},{"id":"mc-0006","title":"Medial versus lateral","category":"Anatomy","level":"Foundation","fact":"Medial points toward the midline; lateral points away from it.","source":"Anatomy"},{"id":"mc-0007","title":"Dermatomes","category":"Anatomy","level":"Foundation","fact":"A dermatome is skin supplied primarily by one spinal nerve root; boundaries overlap and vary.","source":"Anatomy"},{"id":"mc-0008","title":"Myotomes","category":"Anatomy","level":"Foundation","fact":"A myotome groups muscles predominantly supplied by one spinal segment; bedside testing uses representative movements.","source":"Anatomy"},{"id":"mc-0009","title":"Brachial plexus roots","category":"Anatomy","level":"Foundation","fact":"The brachial plexus is formed from anterior rami of C5 through T1 and supplies most of the upper limb.","source":"Anatomy"},{"id":"mc-0010","title":"Axillary nerve","category":"Anatomy","level":"Foundation","fact":"The axillary nerve supplies deltoid and teres minor and carries sensation from the lateral shoulder.","source":"Anatomy"},{"id":"mc-0011","title":"Radial nerve","category":"Anatomy","level":"Foundation","fact":"The radial nerve primarily supplies upper-limb extensors; injury can produce wrist drop.","source":"Anatomy"},{"id":"mc-0012","title":"Median nerve","category":"Anatomy","level":"Foundation","fact":"The median nerve supplies many forearm flexors and thenar muscles; compression at the wrist affects hand sensation and function.","source":"Anatomy"},{"id":"mc-0013","title":"Ulnar nerve","category":"Anatomy","level":"Foundation","fact":"The ulnar nerve supplies most intrinsic hand muscles; lesions can impair finger abduction and adduction.","source":"Anatomy"},{"id":"mc-0014","title":"Femoral nerve","category":"Anatomy","level":"Foundation","fact":"The femoral nerve supplies quadriceps and contributes to the patellar reflex via L2–L4.","source":"Anatomy"},{"id":"mc-0015","title":"Common fibular nerve","category":"Anatomy","level":"Foundation","fact":"The common fibular nerve winds around the fibular neck, where it is vulnerable to injury causing foot drop.","source":"Anatomy"},{"id":"mc-0016","title":"Tibial nerve","category":"Anatomy","level":"Foundation","fact":"The tibial nerve supplies posterior leg muscles and plantar foot sensation through its branches.","source":"Anatomy"},{"id":"mc-0017","title":"Sciatic nerve","category":"Anatomy","level":"Foundation","fact":"The sciatic nerve carries fibers from L4 through S3 and usually divides into tibial and common fibular nerves.","source":"Anatomy"},{"id":"mc-0018","title":"Phrenic nerve","category":"Anatomy","level":"Foundation","fact":"C3–C5 fibers form the phrenic nerve, the principal motor supply to the diaphragm.","source":"Anatomy"},{"id":"mc-0019","title":"Vagus nerve","category":"Anatomy","level":"Foundation","fact":"Cranial nerve X provides parasympathetic innervation to thoracic and much of the abdominal viscera.","source":"Anatomy"},{"id":"mc-0020","title":"Recurrent laryngeal nerve","category":"Anatomy","level":"Foundation","fact":"This vagal branch supplies most intrinsic laryngeal muscles; injury can cause vocal-cord weakness and hoarseness.","source":"Anatomy"},{"id":"mc-0021","title":"Facial nerve","category":"Anatomy","level":"Foundation","fact":"Cranial nerve VII supplies muscles of facial expression and carries taste from the anterior two-thirds of the tongue.","source":"Anatomy"},{"id":"mc-0022","title":"Trigeminal nerve","category":"Anatomy","level":"Foundation","fact":"Cranial nerve V supplies most facial sensation and the muscles of mastication.","source":"Anatomy"},{"id":"mc-0023","title":"Oculomotor nerve","category":"Anatomy","level":"Foundation","fact":"Cranial nerve III supplies most extraocular muscles and parasympathetic pupillary constriction.","source":"Anatomy"},{"id":"mc-0024","title":"Trochlear nerve","category":"Anatomy","level":"Foundation","fact":"Cranial nerve IV innervates superior oblique, which helps depress the adducted eye.","source":"Anatomy"},{"id":"mc-0025","title":"Abducens nerve","category":"Anatomy","level":"Foundation","fact":"Cranial nerve VI innervates lateral rectus and abducts the eye.","source":"Anatomy"},{"id":"mc-0026","title":"Optic chiasm","category":"Anatomy","level":"Foundation","fact":"Nasal retinal fibers cross in the optic chiasm; chiasmal lesions can cause bitemporal visual field loss.","source":"Anatomy"},{"id":"mc-0027","title":"Circle of Willis","category":"Anatomy","level":"Foundation","fact":"The arterial circle connects anterior and posterior cerebral circulations, with substantial anatomical variation.","source":"Anatomy"},{"id":"mc-0028","title":"Middle cerebral artery","category":"Anatomy","level":"Foundation","fact":"The MCA supplies much of the lateral cerebral hemisphere; strokes may affect face and arm more than leg.","source":"Anatomy"},{"id":"mc-0029","title":"Anterior cerebral artery","category":"Anatomy","level":"Foundation","fact":"The ACA supplies medial frontal and parietal cortex; infarction may disproportionately affect the contralateral leg.","source":"Anatomy"},{"id":"mc-0030","title":"Posterior cerebral artery","category":"Anatomy","level":"Foundation","fact":"The PCA supplies occipital cortex; infarction commonly causes a contralateral visual-field defect.","source":"Anatomy"},{"id":"mc-0031","title":"Internal capsule","category":"Anatomy","level":"Foundation","fact":"Dense corticospinal and sensory pathways pass through the internal capsule; small lesions can cause major deficits.","source":"Anatomy"},{"id":"mc-0032","title":"Broca region","category":"Anatomy","level":"Foundation","fact":"The dominant inferior frontal region contributes to speech production; lesions can cause nonfluent aphasia.","source":"Anatomy"},{"id":"mc-0033","title":"Wernicke region","category":"Anatomy","level":"Foundation","fact":"The dominant posterior temporal region contributes to language comprehension; lesions can cause fluent but impaired language.","source":"Anatomy"},{"id":"mc-0034","title":"Basal ganglia","category":"Anatomy","level":"Foundation","fact":"The basal ganglia contribute to movement selection and regulation rather than directly initiating muscle contraction.","source":"Anatomy"},{"id":"mc-0035","title":"Cerebellum","category":"Anatomy","level":"Foundation","fact":"The cerebellum coordinates timing and accuracy of movement; lesions may produce ataxia and dysmetria.","source":"Anatomy"},{"id":"mc-0036","title":"Brainstem","category":"Anatomy","level":"Foundation","fact":"Midbrain, pons and medulla contain cranial nerve nuclei and vital ascending and descending pathways.","source":"Anatomy"},{"id":"mc-0037","title":"Meninges","category":"Anatomy","level":"Foundation","fact":"Dura, arachnoid and pia protect the central nervous system; subarachnoid space contains cerebrospinal fluid.","source":"Anatomy"},{"id":"mc-0038","title":"Ventricular system","category":"Anatomy","level":"Foundation","fact":"CSF passes through lateral ventricles, third ventricle, aqueduct and fourth ventricle before reaching subarachnoid spaces.","source":"Anatomy"},{"id":"mc-0039","title":"Spinal cord termination","category":"Anatomy","level":"Foundation","fact":"In most adults the spinal cord ends near L1–L2, whereas lumbar nerve roots continue as the cauda equina.","source":"Anatomy"},{"id":"mc-0040","title":"Cauda equina","category":"Anatomy","level":"Foundation","fact":"The cauda equina is a bundle of lumbar and sacral nerve roots below the conus medullaris.","source":"Anatomy"},{"id":"mc-0041","title":"Cervical vertebrae","category":"Anatomy","level":"Foundation","fact":"Typical cervical vertebrae have transverse foramina; C1 and C2 are structurally specialized.","source":"Anatomy"},{"id":"mc-0042","title":"Thoracic vertebrae","category":"Anatomy","level":"Foundation","fact":"Thoracic vertebrae articulate with ribs and normally contribute to thoracic kyphosis.","source":"Anatomy"},{"id":"mc-0043","title":"Lumbar vertebrae","category":"Anatomy","level":"Foundation","fact":"Lumbar vertebrae have large bodies adapted for weight bearing.","source":"Anatomy"},{"id":"mc-0044","title":"Intervertebral disc","category":"Anatomy","level":"Foundation","fact":"The nucleus pulposus is surrounded by annulus fibrosus; herniation may compress a spinal root.","source":"Anatomy"},{"id":"mc-0045","title":"Sternocleidomastoid","category":"Anatomy","level":"Foundation","fact":"This muscle rotates the head toward the opposite side and receives motor supply from the accessory nerve.","source":"Anatomy"},{"id":"mc-0046","title":"Rotator cuff","category":"Anatomy","level":"Foundation","fact":"Supraspinatus, infraspinatus, teres minor and subscapularis stabilize the glenohumeral joint.","source":"Anatomy"},{"id":"mc-0047","title":"Carpal tunnel contents","category":"Anatomy","level":"Foundation","fact":"The median nerve and nine flexor tendons traverse the carpal tunnel under the flexor retinaculum.","source":"Anatomy"},{"id":"mc-0048","title":"Anatomical snuffbox","category":"Anatomy","level":"Foundation","fact":"The radial artery crosses the anatomical snuffbox; tenderness after a fall can indicate scaphoid injury.","source":"Anatomy"},{"id":"mc-0049","title":"Femoral triangle","category":"Anatomy","level":"Foundation","fact":"Its major contents proceed laterally to medially as nerve, artery, vein and lymphatics.","source":"Anatomy"},{"id":"mc-0050","title":"Inguinal ligament","category":"Anatomy","level":"Foundation","fact":"The inguinal ligament runs from anterior superior iliac spine to pubic tubercle and helps define the femoral region.","source":"Anatomy"},{"id":"mc-0051","title":"Portal vein","category":"Anatomy","level":"Foundation","fact":"The portal vein forms chiefly from splenic and superior mesenteric veins and drains the gastrointestinal tract to the liver.","source":"Anatomy"},{"id":"mc-0052","title":"Hepatic lobule","category":"Anatomy","level":"Foundation","fact":"Portal triads lie toward lobule peripheries while central veins drain blood toward hepatic veins.","source":"Anatomy"},{"id":"mc-0053","title":"Liver segments","category":"Anatomy","level":"Foundation","fact":"Couinaud segments are based on portal inflow and hepatic venous drainage and guide hepatobiliary anatomy.","source":"Anatomy"},{"id":"mc-0054","title":"Calot triangle","category":"Anatomy","level":"Foundation","fact":"Modern descriptions commonly identify cystic duct, common hepatic duct and inferior liver surface as boundaries of the hepatocystic triangle.","source":"Anatomy"},{"id":"mc-0055","title":"Pancreatic duct","category":"Anatomy","level":"Foundation","fact":"The main pancreatic duct usually joins the common bile duct near the major duodenal papilla.","source":"Anatomy"},{"id":"mc-0056","title":"Spleen","category":"Anatomy","level":"Foundation","fact":"The spleen filters blood and supports immune responses, particularly against encapsulated bacteria.","source":"Anatomy"},{"id":"mc-0057","title":"Nephron components","category":"Anatomy","level":"Foundation","fact":"Glomerulus, proximal tubule, loop of Henle, distal tubule and collecting system perform filtration and selective transport.","source":"Anatomy"},{"id":"mc-0058","title":"Ureter constrictions","category":"Anatomy","level":"Foundation","fact":"The ureter narrows near the pelviureteric junction, iliac crossing and ureterovesical junction, where stones may lodge.","source":"Anatomy"},{"id":"mc-0059","title":"Heart chambers","category":"Anatomy","level":"Foundation","fact":"The right heart receives systemic venous blood; the left heart pumps oxygenated blood to systemic circulation.","source":"Anatomy"},{"id":"mc-0060","title":"Coronary dominance","category":"Anatomy","level":"Foundation","fact":"Coronary dominance is defined by the artery giving rise to the posterior descending artery, usually the right coronary artery.","source":"Anatomy"},{"id":"mc-0061","title":"Aortic valve","category":"Anatomy","level":"Foundation","fact":"The aortic valve lies between left ventricle and ascending aorta and normally has three cusps.","source":"Anatomy"},{"id":"mc-0062","title":"Mitral valve","category":"Anatomy","level":"Foundation","fact":"The mitral valve between left atrium and ventricle has anterior and posterior leaflets supported by chordae and papillary muscles.","source":"Anatomy"},{"id":"mc-0063","title":"Lung lobes","category":"Anatomy","level":"Foundation","fact":"The right lung usually has three lobes and the left two, with a lingula on the left.","source":"Anatomy"},{"id":"mc-0064","title":"Pleural cavity","category":"Anatomy","level":"Foundation","fact":"The potential space between visceral and parietal pleura contains a thin lubricating fluid film.","source":"Anatomy"},{"id":"mc-0065","title":"Bronchopulmonary segment","category":"Anatomy","level":"Foundation","fact":"A bronchopulmonary segment has its own segmental bronchus and arterial branch and is a surgical anatomical unit.","source":"Anatomy"},{"id":"mc-0066","title":"Diaphragmatic openings","category":"Anatomy","level":"Foundation","fact":"The caval opening is near T8, esophageal hiatus T10 and aortic hiatus T12, useful landmarks rather than exact universal levels.","source":"Anatomy"},{"id":"mc-0067","title":"Uterine artery relation","category":"Anatomy","level":"Foundation","fact":"The ureter passes below the uterine artery near the cervix, making it vulnerable in pelvic surgery.","source":"Anatomy"},{"id":"mc-0068","title":"Pelvic floor","category":"Anatomy","level":"Foundation","fact":"Levator ani and coccygeus contribute to pelvic organ support and continence.","source":"Anatomy"},{"id":"mc-0069","title":"Resting membrane potential","category":"Physiology","level":"Foundation","fact":"Resting membrane potential reflects ion gradients and membrane permeability, especially potassium conductance.","source":"Physiology"},{"id":"mc-0070","title":"Action potential upstroke","category":"Physiology","level":"Foundation","fact":"Fast voltage-gated sodium channels produce the rapid upstroke in many neurons and skeletal muscle fibers.","source":"Physiology"},{"id":"mc-0071","title":"Absolute refractory period","category":"Physiology","level":"Foundation","fact":"During the absolute refractory period, inactivated sodium channels prevent a second propagated action potential.","source":"Physiology"},{"id":"mc-0072","title":"Synaptic transmission","category":"Physiology","level":"Foundation","fact":"Calcium entry at a presynaptic terminal triggers vesicular neurotransmitter release.","source":"Physiology"},{"id":"mc-0073","title":"Neuromuscular junction","category":"Physiology","level":"Foundation","fact":"Acetylcholine activates nicotinic receptors at the motor end plate, initiating skeletal muscle excitation.","source":"Physiology"},{"id":"mc-0074","title":"Excitation–contraction coupling","category":"Physiology","level":"Foundation","fact":"In skeletal muscle, T-tubule voltage sensors trigger sarcoplasmic reticulum calcium release.","source":"Physiology"},{"id":"mc-0075","title":"Sliding filament mechanism","category":"Physiology","level":"Foundation","fact":"Actin and myosin slide past one another; sarcomeres shorten without individual filaments becoming shorter.","source":"Physiology"},{"id":"mc-0076","title":"Frank–Starling mechanism","category":"Physiology","level":"Foundation","fact":"Within physiological limits, increased ventricular filling raises stroke volume through length-dependent activation.","source":"Physiology"},{"id":"mc-0077","title":"Cardiac output","category":"Physiology","level":"Foundation","fact":"Cardiac output is heart rate multiplied by stroke volume and changes with preload, afterload and contractility.","source":"Physiology"},{"id":"mc-0078","title":"Mean arterial pressure","category":"Physiology","level":"Foundation","fact":"Mean arterial pressure is influenced by cardiac output and systemic vascular resistance.","source":"Physiology"},{"id":"mc-0079","title":"Baroreceptor reflex","category":"Physiology","level":"Foundation","fact":"Carotid sinus and aortic arch stretch receptors rapidly adjust autonomic outflow when arterial pressure changes.","source":"Physiology"},{"id":"mc-0080","title":"Renin–angiotensin system","category":"Physiology","level":"Foundation","fact":"Renal renin release leads to angiotensin II and aldosterone signaling during low effective circulating volume.","source":"Physiology"},{"id":"mc-0081","title":"Aldosterone action","category":"Physiology","level":"Foundation","fact":"Aldosterone increases distal nephron sodium reabsorption and promotes potassium secretion.","source":"Physiology"},{"id":"mc-0082","title":"ADH action","category":"Physiology","level":"Foundation","fact":"Vasopressin enhances collecting-duct water permeability through aquaporin-2 insertion.","source":"Physiology"},{"id":"mc-0083","title":"Glomerular filtration","category":"Physiology","level":"Foundation","fact":"Filtration depends on glomerular hydraulic pressure, oncotic pressure and filtration-barrier properties.","source":"Physiology"},{"id":"mc-0084","title":"Tubuloglomerular feedback","category":"Physiology","level":"Foundation","fact":"The macula densa senses distal tubular salt delivery and helps adjust afferent arteriolar tone and renin release.","source":"Physiology"},{"id":"mc-0085","title":"Proximal tubule","category":"Physiology","level":"Foundation","fact":"Most filtered sodium, water, bicarbonate and glucose are normally reclaimed in the proximal tubule.","source":"Physiology"},{"id":"mc-0086","title":"Loop of Henle","category":"Physiology","level":"Foundation","fact":"Countercurrent multiplication helps establish a medullary osmotic gradient for urine concentration.","source":"Physiology"},{"id":"mc-0087","title":"Distal potassium handling","category":"Physiology","level":"Foundation","fact":"Potassium secretion depends partly on aldosterone, distal sodium delivery and tubular flow.","source":"Physiology"},{"id":"mc-0088","title":"Acid excretion","category":"Physiology","level":"Foundation","fact":"Kidneys regulate acid–base balance through filtered bicarbonate reclamation and new bicarbonate generation.","source":"Physiology"},{"id":"mc-0089","title":"Ventilation versus perfusion","category":"Physiology","level":"Foundation","fact":"Ventilation supplies alveolar gas while perfusion supplies blood; their matching influences oxygenation.","source":"Physiology"},{"id":"mc-0090","title":"Alveolar ventilation","category":"Physiology","level":"Foundation","fact":"Alveolar ventilation depends on respiratory rate and the portion of tidal volume beyond physiological dead space.","source":"Physiology"},{"id":"mc-0091","title":"Oxygen dissociation curve","category":"Physiology","level":"Foundation","fact":"Hemoglobin affinity decreases with higher carbon dioxide, acidity and temperature, facilitating oxygen unloading.","source":"Physiology"},{"id":"mc-0092","title":"Bohr effect","category":"Physiology","level":"Foundation","fact":"Increased hydrogen ions or carbon dioxide shift hemoglobin–oxygen binding toward oxygen release in tissues.","source":"Physiology"},{"id":"mc-0093","title":"Haldane effect","category":"Physiology","level":"Foundation","fact":"Oxygenation of hemoglobin in the lungs decreases its capacity to carry carbon dioxide.","source":"Physiology"},{"id":"mc-0094","title":"Diffusion capacity","category":"Physiology","level":"Foundation","fact":"Alveolar gas transfer depends on surface area, membrane thickness and properties of the gas.","source":"Physiology"},{"id":"mc-0095","title":"Respiratory drive","category":"Physiology","level":"Foundation","fact":"Central chemoreceptors respond largely to CSF pH changes driven by arterial carbon dioxide.","source":"Physiology"},{"id":"mc-0096","title":"Surfactant function","category":"Physiology","level":"Foundation","fact":"Pulmonary surfactant reduces surface tension and helps prevent alveolar collapse.","source":"Physiology"},{"id":"mc-0097","title":"Compliance","category":"Physiology","level":"Foundation","fact":"Lung compliance describes the change in volume for a given transpulmonary pressure change.","source":"Physiology"},{"id":"mc-0098","title":"Airway resistance","category":"Physiology","level":"Foundation","fact":"Small changes in airway radius markedly affect resistance, particularly in turbulent or obstructed flow.","source":"Physiology"},{"id":"mc-0099","title":"Gastric acid secretion","category":"Physiology","level":"Foundation","fact":"Parietal cell acid secretion is stimulated by acetylcholine, gastrin and histamine signaling.","source":"Physiology"},{"id":"mc-0100","title":"Intrinsic factor","category":"Physiology","level":"Foundation","fact":"Gastric parietal cells release intrinsic factor required for terminal ileal vitamin B12 absorption.","source":"Physiology"},{"id":"mc-0101","title":"Bile acids","category":"Physiology","level":"Foundation","fact":"Bile acids emulsify dietary fat and are recycled through the enterohepatic circulation.","source":"Physiology"},{"id":"mc-0102","title":"Pancreatic enzymes","category":"Physiology","level":"Foundation","fact":"Pancreatic acinar cells produce digestive enzymes while duct cells secrete bicarbonate-rich fluid.","source":"Physiology"},{"id":"mc-0103","title":"Small intestine absorption","category":"Physiology","level":"Foundation","fact":"The small intestine is the principal site of nutrient absorption, aided by villi and microvilli.","source":"Physiology"},{"id":"mc-0104","title":"Colon function","category":"Physiology","level":"Foundation","fact":"The colon absorbs water and electrolytes and hosts extensive microbial metabolism.","source":"Physiology"},{"id":"mc-0105","title":"Insulin signaling","category":"Physiology","level":"Foundation","fact":"Insulin promotes glucose uptake in muscle and adipose tissue and suppresses hepatic glucose output.","source":"Physiology"},{"id":"mc-0106","title":"Glucagon action","category":"Physiology","level":"Foundation","fact":"Glucagon increases hepatic glucose production, especially during fasting.","source":"Physiology"},{"id":"mc-0107","title":"Cortisol physiology","category":"Physiology","level":"Foundation","fact":"Cortisol supports stress responses, vascular responsiveness and metabolic substrate availability.","source":"Physiology"},{"id":"mc-0108","title":"Thyroid hormones","category":"Physiology","level":"Foundation","fact":"Thyroid hormones increase basal metabolic activity and influence cardiovascular and neurological function.","source":"Physiology"},{"id":"mc-0109","title":"PTH action","category":"Physiology","level":"Foundation","fact":"Parathyroid hormone increases serum calcium by affecting bone, kidney and vitamin D activation.","source":"Physiology"},{"id":"mc-0110","title":"Vitamin D activation","category":"Physiology","level":"Foundation","fact":"Vitamin D undergoes hepatic 25-hydroxylation and renal 1-alpha hydroxylation to form active calcitriol.","source":"Physiology"},{"id":"mc-0111","title":"Negative feedback endocrine","category":"Physiology","level":"Foundation","fact":"Many hormone axes regulate output through feedback from downstream hormones to hypothalamus and pituitary.","source":"Physiology"},{"id":"mc-0112","title":"Menstrual cycle follicular phase","category":"Physiology","level":"Foundation","fact":"FSH supports follicular development while estradiol rises ahead of the mid-cycle LH surge.","source":"Physiology"},{"id":"mc-0113","title":"Ovulation","category":"Physiology","level":"Foundation","fact":"A mid-cycle LH surge triggers ovulation, after which progesterone rises during the luteal phase.","source":"Physiology"},{"id":"mc-0114","title":"Placental gas exchange","category":"Physiology","level":"Foundation","fact":"Oxygen and carbon dioxide cross the placenta mainly through diffusion driven by partial-pressure gradients.","source":"Physiology"},{"id":"mc-0115","title":"Fetal circulation","category":"Physiology","level":"Foundation","fact":"The ductus venosus, foramen ovale and ductus arteriosus bypass portions of the fetal liver and pulmonary circulation.","source":"Physiology"},{"id":"mc-0116","title":"Hemostasis primary phase","category":"Physiology","level":"Foundation","fact":"Platelet adhesion, activation and aggregation form an initial plug at vascular injury sites.","source":"Physiology"},{"id":"mc-0117","title":"Coagulation cascade","category":"Physiology","level":"Foundation","fact":"Tissue factor initiates coagulation in vivo, leading to thrombin generation and fibrin formation.","source":"Physiology"},{"id":"mc-0118","title":"Fibrinolysis","category":"Physiology","level":"Foundation","fact":"Plasmin degrades cross-linked fibrin; D-dimer is a degradation product of stabilized fibrin.","source":"Physiology"},{"id":"mc-0119","title":"Iron absorption","category":"Physiology","level":"Foundation","fact":"Dietary iron is absorbed predominantly in the duodenum and proximal jejunum, with hepcidin governing systemic availability.","source":"Physiology"},{"id":"mc-0120","title":"Erythropoietin","category":"Physiology","level":"Foundation","fact":"Renal cells increase erythropoietin production in response to hypoxia, stimulating red-cell formation.","source":"Physiology"},{"id":"mc-0121","title":"Hemoglobin function","category":"Physiology","level":"Foundation","fact":"Hemoglobin binds oxygen cooperatively, allowing efficient loading in lungs and unloading in tissue.","source":"Physiology"},{"id":"mc-0122","title":"Innate immunity","category":"Physiology","level":"Foundation","fact":"Innate immune defenses respond rapidly through barriers, phagocytes, complement and pattern recognition.","source":"Physiology"},{"id":"mc-0123","title":"Adaptive immunity","category":"Physiology","level":"Foundation","fact":"B and T lymphocytes generate antigen-specific responses and immunological memory.","source":"Physiology"},{"id":"mc-0124","title":"Complement pathways","category":"Physiology","level":"Foundation","fact":"Complement can be activated by classical, lectin and alternative routes, converging on C3 activation.","source":"Physiology"},{"id":"mc-0125","title":"Antigen presentation","category":"Physiology","level":"Foundation","fact":"MHC class I presents primarily intracellular peptides to CD8 T cells; class II presents predominantly extracellular peptides to CD4 cells.","source":"Physiology"},{"id":"mc-0126","title":"Pain pathways","category":"Physiology","level":"Foundation","fact":"Nociceptive signals ascend through pathways including the spinothalamic tract and are modulated centrally.","source":"Physiology"},{"id":"mc-0127","title":"Visual phototransduction","category":"Physiology","level":"Foundation","fact":"Light activates retinal photopigments and leads to hyperpolarization of photoreceptor cells.","source":"Physiology"},{"id":"mc-0128","title":"Hearing transduction","category":"Physiology","level":"Foundation","fact":"Movement of cochlear hair-cell stereocilia opens mechanically gated channels and creates receptor potentials.","source":"Physiology"},{"id":"mc-0129","title":"Vestibular function","category":"Physiology","level":"Foundation","fact":"Semicircular canals detect angular acceleration while otolith organs sense linear acceleration and head position.","source":"Physiology"},{"id":"mc-0130","title":"Sleep regulation","category":"Physiology","level":"Foundation","fact":"Homeostatic sleep drive and circadian timing interact, with the suprachiasmatic nucleus as a central clock.","source":"Physiology"},{"id":"mc-0131","title":"Bone remodeling","category":"Physiology","level":"Foundation","fact":"Osteoclast-mediated resorption and osteoblast-mediated formation maintain skeletal structure and mineral homeostasis.","source":"Physiology"},{"id":"mc-0132","title":"Thermoregulation","category":"Physiology","level":"Foundation","fact":"Hypothalamic networks coordinate sweating, shivering and cutaneous blood-flow adjustments.","source":"Physiology"},{"id":"mc-0133","title":"Cellular adaptation hypertrophy","category":"Pathology","level":"Core science","fact":"Hypertrophy increases cell size in response to increased workload or signals, as in pressure-overloaded myocardium.","source":"Pathology"},{"id":"mc-0134","title":"Cellular adaptation hyperplasia","category":"Pathology","level":"Core science","fact":"Hyperplasia increases cell number in tissues capable of proliferation; it may be physiological or pathological.","source":"Pathology"},{"id":"mc-0135","title":"Metaplasia","category":"Pathology","level":"Core science","fact":"Metaplasia is reversible replacement of one differentiated cell type by another under chronic irritation.","source":"Pathology"},{"id":"mc-0136","title":"Dysplasia","category":"Pathology","level":"Core science","fact":"Dysplasia denotes disordered cellular growth and maturation; it is not synonymous with invasive cancer.","source":"Pathology"},{"id":"mc-0137","title":"Apoptosis","category":"Pathology","level":"Core science","fact":"Apoptosis is regulated cell death usually without the marked inflammatory response of necrosis.","source":"Pathology"},{"id":"mc-0138","title":"Coagulative necrosis","category":"Pathology","level":"Core science","fact":"Coagulative necrosis preserves tissue outlines transiently and is typical of many ischemic solid-organ infarcts.","source":"Pathology"},{"id":"mc-0139","title":"Liquefactive necrosis","category":"Pathology","level":"Core science","fact":"Liquefactive necrosis features enzymatic digestion and is characteristic of cerebral infarction and some abscesses.","source":"Pathology"},{"id":"mc-0140","title":"Caseous necrosis","category":"Pathology","level":"Core science","fact":"Caseous necrosis has granular, cheese-like debris and is often associated with tuberculosis granulomas.","source":"Pathology"},{"id":"mc-0141","title":"Granulomatous inflammation","category":"Pathology","level":"Core science","fact":"Granulomas are organized collections of activated macrophages and may occur in infection or immune disease.","source":"Pathology"},{"id":"mc-0142","title":"Acute inflammation","category":"Pathology","level":"Core science","fact":"Neutrophils predominate early in many acute bacterial inflammatory responses.","source":"Pathology"},{"id":"mc-0143","title":"Chronic inflammation","category":"Pathology","level":"Core science","fact":"Chronic inflammation often combines lymphocytes, macrophages, tissue injury and attempted repair.","source":"Pathology"},{"id":"mc-0144","title":"Transudate","category":"Pathology","level":"Core science","fact":"A transudate generally arises from altered hydrostatic or oncotic forces without primary inflammation.","source":"Pathology"},{"id":"mc-0145","title":"Exudate","category":"Pathology","level":"Core science","fact":"An exudate typically reflects increased vascular permeability and local inflammation.","source":"Pathology"},{"id":"mc-0146","title":"Virchow triad","category":"Pathology","level":"Core science","fact":"Thrombosis risk is influenced by endothelial injury, abnormal blood flow and hypercoagulability.","source":"Pathology"},{"id":"mc-0147","title":"Embolus","category":"Pathology","level":"Core science","fact":"An embolus is material traveling in circulation to occlude a vessel distant from its origin.","source":"Pathology"},{"id":"mc-0148","title":"Reperfusion injury","category":"Pathology","level":"Core science","fact":"Restored flow can trigger oxidative and inflammatory injury in previously ischemic tissues.","source":"Pathology"},{"id":"mc-0149","title":"Amyloidosis","category":"Pathology","level":"Core science","fact":"Amyloid deposition involves misfolded extracellular protein fibrils and can impair multiple organs.","source":"Pathology"},{"id":"mc-0150","title":"Fibrosis","category":"Pathology","level":"Core science","fact":"Fibrosis is excessive extracellular matrix deposition following chronic injury and repair.","source":"Pathology"},{"id":"mc-0151","title":"Oncogene","category":"Pathology","level":"Core science","fact":"An activated oncogene can promote proliferation or survival signaling in neoplastic cells.","source":"Pathology"},{"id":"mc-0152","title":"Tumor suppressor gene","category":"Pathology","level":"Core science","fact":"Loss of tumor suppressor function removes constraints on cell growth or genomic integrity.","source":"Pathology"},{"id":"mc-0153","title":"Metastasis","category":"Pathology","level":"Core science","fact":"Metastasis requires tumor cells to spread and establish growth at a distant site.","source":"Pathology"},{"id":"mc-0154","title":"Carcinoma versus sarcoma","category":"Pathology","level":"Core science","fact":"Carcinomas arise from epithelial cells, while sarcomas derive from mesenchymal tissues.","source":"Pathology"},{"id":"mc-0155","title":"Tumor grading","category":"Pathology","level":"Core science","fact":"Histological grade describes tumor differentiation and proliferative aggressiveness rather than anatomical extent.","source":"Pathology"},{"id":"mc-0156","title":"Tumor staging","category":"Pathology","level":"Core science","fact":"Cancer stage describes extent of disease and often considers primary tumor, nodal involvement and metastases.","source":"Pathology"},{"id":"mc-0157","title":"Ductal carcinoma in situ","category":"Pathology","level":"Core science","fact":"DCIS is neoplastic ductal epithelial proliferation confined by the basement membrane.","source":"Pathology"},{"id":"mc-0158","title":"Adenoma","category":"Pathology","level":"Core science","fact":"An adenoma is a benign epithelial neoplasm with glandular differentiation or origin.","source":"Pathology"},{"id":"mc-0159","title":"Lymphoma","category":"Pathology","level":"Core science","fact":"Lymphomas are neoplasms of lymphoid cells and differ in behavior by subtype.","source":"Pathology"},{"id":"mc-0160","title":"Leukemia","category":"Pathology","level":"Core science","fact":"Leukemias involve malignant hematopoietic cells, frequently affecting marrow and blood.","source":"Pathology"},{"id":"mc-0161","title":"Myelodysplastic neoplasm","category":"Pathology","level":"Core science","fact":"Myelodysplastic neoplasms feature ineffective hematopoiesis with dysplastic marrow cell lines.","source":"Pathology"},{"id":"mc-0162","title":"Hemolytic anemia","category":"Pathology","level":"Core science","fact":"Hemolytic anemia results from accelerated red-cell destruction, often with raised reticulocytes and indirect bilirubin.","source":"Pathology"},{"id":"mc-0163","title":"Iron deficiency anemia","category":"Pathology","level":"Core science","fact":"Iron deficiency typically causes microcytic hypochromic anemia, although early disease can be normocytic.","source":"Pathology"},{"id":"mc-0164","title":"Megaloblastic anemia","category":"Pathology","level":"Core science","fact":"B12 or folate deficiency impairs DNA synthesis and often produces macrocytosis with hypersegmented neutrophils.","source":"Pathology"},{"id":"mc-0165","title":"Anemia of inflammation","category":"Pathology","level":"Core science","fact":"Inflammatory hepcidin signaling reduces available iron and may suppress erythropoiesis.","source":"Pathology"},{"id":"mc-0166","title":"Sickle cell disease","category":"Pathology","level":"Core science","fact":"Hemoglobin S polymerization under deoxygenation leads to hemolysis and vaso-occlusive injury.","source":"Pathology"},{"id":"mc-0167","title":"Thalassemia","category":"Pathology","level":"Core science","fact":"Thalassemias are inherited defects in globin-chain production causing imbalanced hemoglobin synthesis.","source":"Pathology"},{"id":"mc-0168","title":"Disseminated intravascular coagulation","category":"Pathology","level":"Core science","fact":"DIC involves systemic activation of coagulation with microthrombi and consumption of platelets and factors.","source":"Pathology"},{"id":"mc-0169","title":"Immune thrombocytopenia","category":"Pathology","level":"Core science","fact":"ITP causes immune-mediated platelet loss, usually with otherwise isolated thrombocytopenia.","source":"Pathology"},{"id":"mc-0170","title":"Thrombotic microangiopathy","category":"Pathology","level":"Core science","fact":"Microangiopathic hemolysis with thrombocytopenia suggests endothelial microvascular injury and requires urgent evaluation.","source":"Pathology"},{"id":"mc-0171","title":"Glomerulonephritis","category":"Pathology","level":"Core science","fact":"Glomerular inflammation may cause hematuria, proteinuria, hypertension and impaired kidney function.","source":"Pathology"},{"id":"mc-0172","title":"Nephrotic syndrome","category":"Pathology","level":"Core science","fact":"Nephrotic syndrome features heavy proteinuria, hypoalbuminemia and edema with increased thrombosis risk.","source":"Pathology"},{"id":"mc-0173","title":"Acute tubular injury","category":"Pathology","level":"Core science","fact":"Acute tubular injury follows ischemic or toxic insults and can impair urinary concentrating and solute handling.","source":"Pathology"},{"id":"mc-0174","title":"Diabetic nephropathy","category":"Pathology","level":"Core science","fact":"Diabetic kidney disease often develops progressive albuminuria and loss of filtration, though patterns vary.","source":"Pathology"},{"id":"mc-0175","title":"Atherosclerosis","category":"Pathology","level":"Core science","fact":"Atherosclerotic plaques contain lipids, inflammatory cells and fibrous tissue in arterial walls.","source":"Pathology"},{"id":"mc-0176","title":"Myocardial infarction pathology","category":"Pathology","level":"Core science","fact":"Ischemic myocyte necrosis evolves over time with inflammatory clearance and subsequent scar formation.","source":"Pathology"},{"id":"mc-0177","title":"Heart failure remodeling","category":"Pathology","level":"Core science","fact":"Chronic hemodynamic stress can change ventricular geometry and promote fibrosis.","source":"Pathology"},{"id":"mc-0178","title":"Cardiac hypertrophy","category":"Pathology","level":"Core science","fact":"Pressure overload tends toward concentric remodeling, while volume overload more often causes eccentric enlargement.","source":"Pathology"},{"id":"mc-0179","title":"Bronchiectasis","category":"Pathology","level":"Core science","fact":"Bronchiectasis is abnormal persistent bronchial dilation associated with recurrent infection and impaired clearance.","source":"Pathology"},{"id":"mc-0180","title":"Emphysema","category":"Pathology","level":"Core science","fact":"Emphysema involves destruction of alveolar walls with enlarged distal airspaces and reduced elastic recoil.","source":"Pathology"},{"id":"mc-0181","title":"Pulmonary fibrosis","category":"Pathology","level":"Core science","fact":"Interstitial fibrosis thickens gas-exchange barriers and causes restrictive physiology.","source":"Pathology"},{"id":"mc-0182","title":"ARDS pathology","category":"Pathology","level":"Core science","fact":"Diffuse alveolar injury and permeability edema characterize many cases of acute respiratory distress syndrome.","source":"Pathology"},{"id":"mc-0183","title":"Cirrhosis","category":"Pathology","level":"Core science","fact":"Cirrhosis involves diffuse fibrosis and regenerative nodules that distort hepatic architecture.","source":"Pathology"},{"id":"mc-0184","title":"Fatty liver disease","category":"Pathology","level":"Core science","fact":"Hepatic steatosis reflects fat accumulation in hepatocytes and may coexist with inflammation and fibrosis.","source":"Pathology"},{"id":"mc-0185","title":"Acute pancreatitis pathology","category":"Pathology","level":"Core science","fact":"Premature pancreatic enzyme activation contributes to acinar injury and local inflammation.","source":"Pathology"},{"id":"mc-0186","title":"Peptic ulcer","category":"Pathology","level":"Core science","fact":"A peptic ulcer penetrates through the muscularis mucosa, usually in acid-exposed gastrointestinal mucosa.","source":"Pathology"},{"id":"mc-0187","title":"Celiac disease pathology","category":"Pathology","level":"Core science","fact":"Celiac disease causes immune-mediated small bowel injury with villous atrophy in susceptible individuals.","source":"Pathology"},{"id":"mc-0188","title":"Inflammatory bowel disease","category":"Pathology","level":"Core science","fact":"Crohn disease may be transmural and discontinuous; ulcerative colitis generally begins in the rectum and is continuous.","source":"Pathology"},{"id":"mc-0189","title":"Alzheimer pathology","category":"Pathology","level":"Core science","fact":"Extracellular amyloid plaques and intracellular tau neurofibrillary tangles are hallmark lesions of Alzheimer disease.","source":"Pathology"},{"id":"mc-0190","title":"Parkinson pathology","category":"Pathology","level":"Core science","fact":"Degeneration of substantia nigra dopaminergic neurons contributes to Parkinson motor symptoms.","source":"Pathology"},{"id":"mc-0191","title":"Multiple sclerosis pathology","category":"Pathology","level":"Core science","fact":"Multiple sclerosis causes inflammatory demyelinating lesions within the central nervous system.","source":"Pathology"},{"id":"mc-0192","title":"Osteoarthritis pathology","category":"Pathology","level":"Core science","fact":"Osteoarthritis combines articular cartilage loss with subchondral bone changes and osteophytes.","source":"Pathology"},{"id":"mc-0193","title":"Rheumatoid synovitis","category":"Pathology","level":"Core science","fact":"Rheumatoid arthritis causes chronic inflammatory synovitis that can erode cartilage and bone.","source":"Pathology"},{"id":"mc-0194","title":"Osteoporosis pathology","category":"Pathology","level":"Core science","fact":"Osteoporosis reduces bone strength and increases fragility fracture risk without requiring abnormal mineralization.","source":"Pathology"},{"id":"mc-0195","title":"Tuberculous granuloma","category":"Pathology","level":"Core science","fact":"Tuberculous granulomas often show caseation but necrosis is neither universal nor exclusive to tuberculosis.","source":"Pathology"},{"id":"mc-0196","title":"Sarcoidosis","category":"Pathology","level":"Core science","fact":"Sarcoidosis is a multisystem granulomatous condition often associated with non-necrotizing granulomas.","source":"Pathology"},{"id":"mc-0197","title":"Giant cell arteritis","category":"Pathology","level":"Core science","fact":"Inflammation of medium and large arteries can threaten vision and is associated with polymyalgia rheumatica.","source":"Pathology"},{"id":"mc-0198","title":"Gram-positive cell wall","category":"Microbiology & Immunology","level":"Core science","fact":"Gram-positive bacteria have a thick peptidoglycan layer that retains crystal violet in the Gram stain.","source":"Microbiology & Immunology"},{"id":"mc-0199","title":"Gram-negative outer membrane","category":"Microbiology & Immunology","level":"Core science","fact":"Gram-negative bacteria have an outer membrane containing lipopolysaccharide, which can trigger inflammatory responses.","source":"Microbiology & Immunology"},{"id":"mc-0200","title":"Acid-fast organisms","category":"Microbiology & Immunology","level":"Core science","fact":"Mycobacteria resist acid-alcohol decolorization because of lipid-rich cell walls containing mycolic acids.","source":"Microbiology & Immunology"},{"id":"mc-0201","title":"Bacterial endospore","category":"Microbiology & Immunology","level":"Core science","fact":"Bacillus and Clostridium species can form resistant spores that persist in harsh environments.","source":"Microbiology & Immunology"},{"id":"mc-0202","title":"Normal microbiota","category":"Microbiology & Immunology","level":"Core science","fact":"Commensal organisms occupy host niches and influence colonization resistance and immune development.","source":"Microbiology & Immunology"},{"id":"mc-0203","title":"Biofilm","category":"Microbiology & Immunology","level":"Core science","fact":"A biofilm is a structured microbial community that can resist host defenses and antimicrobial penetration.","source":"Microbiology & Immunology"},{"id":"mc-0204","title":"Staphylococcus aureus","category":"Microbiology & Immunology","level":"Core science","fact":"S. aureus is catalase-positive and coagulase-positive and can cause skin infection, bacteremia and endocarditis.","source":"Microbiology & Immunology"},{"id":"mc-0205","title":"Coagulase-negative staphylococci","category":"Microbiology & Immunology","level":"Core science","fact":"These skin commensals can cause infection of prosthetic devices and also frequently contaminate blood cultures.","source":"Microbiology & Immunology"},{"id":"mc-0206","title":"Streptococcus pyogenes","category":"Microbiology & Immunology","level":"Core science","fact":"Group A streptococcus causes pharyngitis and soft-tissue infection and can precede immune complications.","source":"Microbiology & Immunology"},{"id":"mc-0207","title":"Streptococcus pneumoniae","category":"Microbiology & Immunology","level":"Core science","fact":"Pneumococcus is encapsulated and can cause pneumonia, meningitis and invasive infection.","source":"Microbiology & Immunology"},{"id":"mc-0208","title":"Enterococcus","category":"Microbiology & Immunology","level":"Core science","fact":"Enterococci inhabit the gastrointestinal tract and may cause urinary, bloodstream and endovascular infections.","source":"Microbiology & Immunology"},{"id":"mc-0209","title":"Clostridioides difficile","category":"Microbiology & Immunology","level":"Core science","fact":"C. difficile can cause toxin-mediated colitis after microbiome disruption, particularly following antibiotics.","source":"Microbiology & Immunology"},{"id":"mc-0210","title":"Clostridium tetani","category":"Microbiology & Immunology","level":"Core science","fact":"Tetanus toxin blocks inhibitory neurotransmitter release, causing spastic muscular contractions.","source":"Microbiology & Immunology"},{"id":"mc-0211","title":"Clostridium botulinum","category":"Microbiology & Immunology","level":"Core science","fact":"Botulinum toxin blocks acetylcholine release, producing flaccid paralysis.","source":"Microbiology & Immunology"},{"id":"mc-0212","title":"Neisseria meningitidis","category":"Microbiology & Immunology","level":"Core science","fact":"Meningococcus is an encapsulated gram-negative diplococcus that can cause meningitis and fulminant sepsis.","source":"Microbiology & Immunology"},{"id":"mc-0213","title":"Neisseria gonorrhoeae","category":"Microbiology & Immunology","level":"Core science","fact":"Gonococcus infects mucosal epithelia and can cause urethritis, cervicitis or disseminated infection.","source":"Microbiology & Immunology"},{"id":"mc-0214","title":"Escherichia coli","category":"Microbiology & Immunology","level":"Core science","fact":"E. coli is a common cause of urinary tract infection, bacteremia and several gastrointestinal syndromes.","source":"Microbiology & Immunology"},{"id":"mc-0215","title":"Klebsiella pneumoniae","category":"Microbiology & Immunology","level":"Core science","fact":"Klebsiella species can cause pneumonia and invasive infection; resistance mechanisms may complicate therapy.","source":"Microbiology & Immunology"},{"id":"mc-0216","title":"Pseudomonas aeruginosa","category":"Microbiology & Immunology","level":"Core science","fact":"Pseudomonas is an opportunistic gram-negative organism associated with healthcare infection and intrinsic resistance.","source":"Microbiology & Immunology"},{"id":"mc-0217","title":"Acinetobacter baumannii","category":"Microbiology & Immunology","level":"Core science","fact":"A. baumannii can persist in healthcare environments and cause difficult-to-treat invasive infection.","source":"Microbiology & Immunology"},{"id":"mc-0218","title":"Salmonella Typhi","category":"Microbiology & Immunology","level":"Core science","fact":"Typhoid fever is a systemic infection acquired through contaminated food or water, with bloodstream dissemination.","source":"Microbiology & Immunology"},{"id":"mc-0219","title":"Shigella","category":"Microbiology & Immunology","level":"Core science","fact":"Shigella can cause inflammatory diarrhea and spreads readily through fecal-oral transmission.","source":"Microbiology & Immunology"},{"id":"mc-0220","title":"Vibrio cholerae","category":"Microbiology & Immunology","level":"Core science","fact":"Cholera toxin raises intestinal cAMP and causes profuse secretory diarrhea and severe dehydration.","source":"Microbiology & Immunology"},{"id":"mc-0221","title":"Campylobacter jejuni","category":"Microbiology & Immunology","level":"Core science","fact":"Campylobacter commonly causes inflammatory diarrhea and may precede Guillain–Barré syndrome.","source":"Microbiology & Immunology"},{"id":"mc-0222","title":"Helicobacter pylori","category":"Microbiology & Immunology","level":"Core science","fact":"H. pylori colonizes gastric mucosa and is associated with peptic ulcer disease and gastric cancer risk.","source":"Microbiology & Immunology"},{"id":"mc-0223","title":"Mycobacterium tuberculosis","category":"Microbiology & Immunology","level":"Core science","fact":"Tuberculosis can remain latent after infection and may reactivate when cell-mediated immunity weakens.","source":"Microbiology & Immunology"},{"id":"mc-0224","title":"Mycobacterium leprae","category":"Microbiology & Immunology","level":"Core science","fact":"M. leprae affects skin and peripheral nerves, leading to sensory changes and possible disability.","source":"Microbiology & Immunology"},{"id":"mc-0225","title":"Treponema pallidum","category":"Microbiology & Immunology","level":"Core science","fact":"Syphilis progresses through variable clinical stages and can affect nervous and cardiovascular systems.","source":"Microbiology & Immunology"},{"id":"mc-0226","title":"Borrelia burgdorferi","category":"Microbiology & Immunology","level":"Core science","fact":"Lyme borreliosis is transmitted by Ixodes ticks and can involve skin, joints, heart and nervous system.","source":"Microbiology & Immunology"},{"id":"mc-0227","title":"Leptospira","category":"Microbiology & Immunology","level":"Core science","fact":"Leptospirosis follows exposure to animal-contaminated water and may cause renal, hepatic or pulmonary injury.","source":"Microbiology & Immunology"},{"id":"mc-0228","title":"Rickettsial diseases","category":"Microbiology & Immunology","level":"Core science","fact":"Rickettsial infections are vector-borne and often involve endothelial injury, fever and rash.","source":"Microbiology & Immunology"},{"id":"mc-0229","title":"Chlamydia trachomatis","category":"Microbiology & Immunology","level":"Core science","fact":"Chlamydia is an obligate intracellular organism causing sexually transmitted and ocular infections.","source":"Microbiology & Immunology"},{"id":"mc-0230","title":"Mycoplasma pneumoniae","category":"Microbiology & Immunology","level":"Core science","fact":"Mycoplasma lacks a cell wall and can produce respiratory infection, making beta-lactams ineffective against it.","source":"Microbiology & Immunology"},{"id":"mc-0231","title":"Legionella pneumophila","category":"Microbiology & Immunology","level":"Core science","fact":"Legionella is an intracellular water-associated pathogen that can cause atypical pneumonia.","source":"Microbiology & Immunology"},{"id":"mc-0232","title":"Influenza virus","category":"Microbiology & Immunology","level":"Core science","fact":"Influenza undergoes antigenic drift through mutation; reassortment may produce antigenic shift in influenza A.","source":"Microbiology & Immunology"},{"id":"mc-0233","title":"SARS-CoV-2","category":"Microbiology & Immunology","level":"Core science","fact":"SARS-CoV-2 infects cells via ACE2-related entry pathways and causes illness with variable respiratory and systemic effects.","source":"Microbiology & Immunology"},{"id":"mc-0234","title":"Respiratory syncytial virus","category":"Microbiology & Immunology","level":"Core science","fact":"RSV is a major cause of bronchiolitis in infants and can cause severe infection in older adults.","source":"Microbiology & Immunology"},{"id":"mc-0235","title":"Measles virus","category":"Microbiology & Immunology","level":"Core science","fact":"Measles is highly contagious and can cause transient immune suppression and severe respiratory or neurologic complications.","source":"Microbiology & Immunology"},{"id":"mc-0236","title":"Varicella-zoster virus","category":"Microbiology & Immunology","level":"Core science","fact":"Primary VZV infection causes chickenpox; later reactivation can produce shingles.","source":"Microbiology & Immunology"},{"id":"mc-0237","title":"Herpes simplex virus","category":"Microbiology & Immunology","level":"Core science","fact":"HSV establishes latency in sensory ganglia and may reactivate, causing recurrent mucocutaneous disease.","source":"Microbiology & Immunology"},{"id":"mc-0238","title":"Epstein–Barr virus","category":"Microbiology & Immunology","level":"Core science","fact":"EBV infects B cells and is linked to infectious mononucleosis and several malignancies.","source":"Microbiology & Immunology"},{"id":"mc-0239","title":"Cytomegalovirus","category":"Microbiology & Immunology","level":"Core science","fact":"CMV may cause severe disease in immunocompromised patients and congenital infection in pregnancy.","source":"Microbiology & Immunology"},{"id":"mc-0240","title":"Hepatitis A virus","category":"Microbiology & Immunology","level":"Core science","fact":"HAV is primarily fecal-oral and does not establish chronic infection.","source":"Microbiology & Immunology"},{"id":"mc-0241","title":"Hepatitis B virus","category":"Microbiology & Immunology","level":"Core science","fact":"HBV spreads through blood and bodily fluids and can lead to chronic infection, cirrhosis and hepatocellular carcinoma.","source":"Microbiology & Immunology"},{"id":"mc-0242","title":"Hepatitis C virus","category":"Microbiology & Immunology","level":"Core science","fact":"HCV is commonly blood-borne and frequently becomes chronic without treatment.","source":"Microbiology & Immunology"},{"id":"mc-0243","title":"HIV entry","category":"Microbiology & Immunology","level":"Core science","fact":"HIV uses CD4 and coreceptors such as CCR5 or CXCR4 to enter susceptible immune cells.","source":"Microbiology & Immunology"},{"id":"mc-0244","title":"Rabies virus","category":"Microbiology & Immunology","level":"Core science","fact":"Rabies travels along peripheral nerves toward the CNS; prophylaxis after exposure is time-sensitive.","source":"Microbiology & Immunology"},{"id":"mc-0245","title":"Human papillomavirus","category":"Microbiology & Immunology","level":"Core science","fact":"Persistent infection with oncogenic HPV types contributes to cervical and several anogenital or oropharyngeal cancers.","source":"Microbiology & Immunology"},{"id":"mc-0246","title":"Rotavirus","category":"Microbiology & Immunology","level":"Core science","fact":"Rotavirus causes severe watery diarrhea especially in unvaccinated young children.","source":"Microbiology & Immunology"},{"id":"mc-0247","title":"Norovirus","category":"Microbiology & Immunology","level":"Core science","fact":"Norovirus spreads efficiently in groups and causes acute vomiting and diarrhea.","source":"Microbiology & Immunology"},{"id":"mc-0248","title":"Candida albicans","category":"Microbiology & Immunology","level":"Core science","fact":"Candida can cause mucocutaneous disease and invasive infection when host barriers or immunity are compromised.","source":"Microbiology & Immunology"},{"id":"mc-0249","title":"Aspergillus fumigatus","category":"Microbiology & Immunology","level":"Core science","fact":"Aspergillus may cause allergy, fungus balls or invasive disease depending on host factors.","source":"Microbiology & Immunology"},{"id":"mc-0250","title":"Cryptococcus neoformans","category":"Microbiology & Immunology","level":"Core science","fact":"Cryptococcus is an encapsulated yeast that can cause meningitis, especially with impaired cell-mediated immunity.","source":"Microbiology & Immunology"},{"id":"mc-0251","title":"Pneumocystis jirovecii","category":"Microbiology & Immunology","level":"Core science","fact":"Pneumocystis pneumonia is associated with cellular immunosuppression and diffuse respiratory illness.","source":"Microbiology & Immunology"},{"id":"mc-0252","title":"Malaria lifecycle","category":"Microbiology & Immunology","level":"Core science","fact":"Plasmodium infects hepatocytes before red cells; cyclical erythrocyte rupture contributes to malaria symptoms.","source":"Microbiology & Immunology"},{"id":"mc-0253","title":"Plasmodium falciparum","category":"Microbiology & Immunology","level":"Core science","fact":"P. falciparum can cause severe malaria with organ dysfunction through infected erythrocyte sequestration.","source":"Microbiology & Immunology"},{"id":"mc-0254","title":"Dengue virus","category":"Microbiology & Immunology","level":"Core science","fact":"Dengue is transmitted by Aedes mosquitoes; plasma leakage can develop around defervescence in severe cases.","source":"Microbiology & Immunology"},{"id":"mc-0255","title":"Leishmania","category":"Microbiology & Immunology","level":"Core science","fact":"Leishmania parasites are transmitted by sandflies and cause cutaneous, mucosal or visceral disease.","source":"Microbiology & Immunology"},{"id":"mc-0256","title":"Schistosoma","category":"Microbiology & Immunology","level":"Core science","fact":"Schistosome cercariae penetrate skin in freshwater and eggs drive much of the chronic inflammatory pathology.","source":"Microbiology & Immunology"},{"id":"mc-0257","title":"Toxoplasma gondii","category":"Microbiology & Immunology","level":"Core science","fact":"Toxoplasma may cause severe congenital infection or reactivated encephalitis with impaired immunity.","source":"Microbiology & Immunology"},{"id":"mc-0258","title":"Echinococcus","category":"Microbiology & Immunology","level":"Core science","fact":"Hydatid cysts from echinococcal infection can involve liver and lung; handling requires specialist precautions.","source":"Microbiology & Immunology"},{"id":"mc-0259","title":"Ascaris","category":"Microbiology & Immunology","level":"Core science","fact":"Ascaris lumbricoides is an intestinal nematode that may cause obstruction with a high worm burden.","source":"Microbiology & Immunology"},{"id":"mc-0260","title":"Hookworm","category":"Microbiology & Immunology","level":"Core science","fact":"Hookworm causes chronic intestinal blood loss and can contribute to iron deficiency anemia.","source":"Microbiology & Immunology"},{"id":"mc-0261","title":"Scabies","category":"Microbiology & Immunology","level":"Core science","fact":"Sarcoptes scabiei mites burrow in skin and cause intense pruritus, often worse at night.","source":"Microbiology & Immunology"},{"id":"mc-0262","title":"Antibiotic susceptibility","category":"Microbiology & Immunology","level":"Core science","fact":"Susceptibility tests report growth inhibition under standardized conditions, which must be interpreted with site and exposure.","source":"Microbiology & Immunology"},{"id":"mc-0263","title":"Colonization versus infection","category":"Microbiology & Immunology","level":"Core science","fact":"Presence of an organism does not prove tissue invasion or the need for antimicrobial therapy.","source":"Microbiology & Immunology"},{"id":"mc-0264","title":"Sterilization versus disinfection","category":"Microbiology & Immunology","level":"Core science","fact":"Sterilization eliminates all viable microorganisms including spores; disinfection reduces organisms to specified levels.","source":"Microbiology & Immunology"},{"id":"mc-0265","title":"Standard precautions","category":"Microbiology & Immunology","level":"Core science","fact":"Hand hygiene and appropriate barriers are applied based on exposure risk regardless of known infection status.","source":"Microbiology & Immunology"},{"id":"mc-0266","title":"Contact precautions","category":"Microbiology & Immunology","level":"Core science","fact":"Contact precautions reduce spread through direct or environmental contact for selected pathogens.","source":"Microbiology & Immunology"},{"id":"mc-0267","title":"Droplet precautions","category":"Microbiology & Immunology","level":"Core science","fact":"Droplet precautions aim to prevent close-range transmission from larger respiratory particles.","source":"Microbiology & Immunology"},{"id":"mc-0268","title":"Airborne precautions","category":"Microbiology & Immunology","level":"Core science","fact":"Airborne precautions require specific respiratory protection and environmental measures for selected airborne pathogens.","source":"Microbiology & Immunology"},{"id":"mc-0269","title":"Vaccination memory","category":"Microbiology & Immunology","level":"Core science","fact":"Vaccines stimulate protective immune responses and memory without requiring the disease's full risk.","source":"Microbiology & Immunology"},{"id":"mc-0270","title":"Herd effects","category":"Microbiology & Immunology","level":"Core science","fact":"High population immunity can reduce transmission risk for susceptible people, depending on pathogen biology.","source":"Microbiology & Immunology"},{"id":"mc-0271","title":"Type I hypersensitivity","category":"Microbiology & Immunology","level":"Core science","fact":"IgE-mediated mast-cell activation produces immediate reactions including urticaria or anaphylaxis.","source":"Microbiology & Immunology"},{"id":"mc-0272","title":"Type II hypersensitivity","category":"Microbiology & Immunology","level":"Core science","fact":"Antibodies targeting cells or tissues cause damage through complement, cellular mechanisms or receptor effects.","source":"Microbiology & Immunology"},{"id":"mc-0273","title":"Type III hypersensitivity","category":"Microbiology & Immunology","level":"Core science","fact":"Immune-complex deposition can trigger complement activation and tissue inflammation.","source":"Microbiology & Immunology"},{"id":"mc-0274","title":"Type IV hypersensitivity","category":"Microbiology & Immunology","level":"Core science","fact":"Delayed hypersensitivity is driven largely by antigen-specific T cells, as in many contact dermatitis reactions.","source":"Microbiology & Immunology"},{"id":"mc-0275","title":"Primary immunodeficiency","category":"Microbiology & Immunology","level":"Core science","fact":"Inherited immune defects can present with characteristic recurrent, severe or unusual infections.","source":"Microbiology & Immunology"},{"id":"mc-0276","title":"Secondary immunodeficiency","category":"Microbiology & Immunology","level":"Core science","fact":"Immunosuppressive drugs, malnutrition, malignancy and HIV can impair immune defense.","source":"Microbiology & Immunology"},{"id":"mc-0277","title":"Pharmacokinetics","category":"Pharmacology","level":"Clinical","fact":"Pharmacokinetics describes absorption, distribution, metabolism and elimination of a medicine.","source":"Pharmacology"},{"id":"mc-0278","title":"Pharmacodynamics","category":"Pharmacology","level":"Clinical","fact":"Pharmacodynamics describes drug effects at molecular targets and the resulting physiologic response.","source":"Pharmacology"},{"id":"mc-0279","title":"Bioavailability","category":"Pharmacology","level":"Clinical","fact":"Bioavailability is the fraction of a dose reaching systemic circulation unchanged.","source":"Pharmacology"},{"id":"mc-0280","title":"Volume of distribution","category":"Pharmacology","level":"Clinical","fact":"Apparent distribution volume relates the amount of drug in the body to its plasma concentration.","source":"Pharmacology"},{"id":"mc-0281","title":"Clearance","category":"Pharmacology","level":"Clinical","fact":"Clearance is the volume of plasma from which drug is effectively removed per unit time.","source":"Pharmacology"},{"id":"mc-0282","title":"Half-life and steady state","category":"Pharmacology","level":"Clinical","fact":"For first-order elimination, drug concentrations approach steady state over several elimination half-lives.","source":"Pharmacology"},{"id":"mc-0283","title":"First-pass metabolism","category":"Pharmacology","level":"Clinical","fact":"Absorbed oral medicines may undergo metabolism in gut wall or liver before systemic circulation.","source":"Pharmacology"},{"id":"mc-0284","title":"Protein binding","category":"Pharmacology","level":"Clinical","fact":"Only unbound drug usually equilibrates readily with tissues and is available for filtration or receptor interaction.","source":"Pharmacology"},{"id":"mc-0285","title":"Therapeutic index","category":"Pharmacology","level":"Clinical","fact":"A narrow therapeutic index means relatively small changes in exposure may produce toxicity or loss of effect.","source":"Pharmacology"},{"id":"mc-0286","title":"Agonist efficacy","category":"Pharmacology","level":"Clinical","fact":"An agonist activates its receptor; partial agonists have lower maximal effect than full agonists at a given system.","source":"Pharmacology"},{"id":"mc-0287","title":"Competitive antagonism","category":"Pharmacology","level":"Clinical","fact":"A reversible competitive antagonist shifts an agonist response curve rightward in an ideal system.","source":"Pharmacology"},{"id":"mc-0288","title":"Tolerance","category":"Pharmacology","level":"Clinical","fact":"Tolerance is reduced drug response after repeated exposure and has pharmacodynamic or pharmacokinetic mechanisms.","source":"Pharmacology"},{"id":"mc-0289","title":"Tachyphylaxis","category":"Pharmacology","level":"Clinical","fact":"Tachyphylaxis describes unusually rapid loss of response with repeated administration.","source":"Pharmacology"},{"id":"mc-0290","title":"Cytochrome P450 interactions","category":"Pharmacology","level":"Clinical","fact":"CYP enzyme inhibition may raise substrate exposure while induction may lower it after time-dependent changes.","source":"Pharmacology"},{"id":"mc-0291","title":"Renal dose consideration","category":"Pharmacology","level":"Clinical","fact":"Reduced kidney function can increase exposure to renally cleared drugs, requiring agent-specific review.","source":"Pharmacology"},{"id":"mc-0292","title":"Hepatic dose consideration","category":"Pharmacology","level":"Clinical","fact":"Liver disease can alter metabolism, protein binding and first-pass handling; drug-specific guidance is essential.","source":"Pharmacology"},{"id":"mc-0293","title":"Medication reconciliation","category":"Pharmacology","level":"Clinical","fact":"Medication reconciliation compares accurate pre-existing medicines with new orders at care transitions.","source":"Pharmacology"},{"id":"mc-0294","title":"Adverse drug reaction","category":"Pharmacology","level":"Clinical","fact":"An adverse reaction is a harmful unintended response at normal therapeutic use, distinct from dosing error.","source":"Pharmacology"},{"id":"mc-0295","title":"Drug allergy versus intolerance","category":"Pharmacology","level":"Clinical","fact":"Immune-mediated allergy must be distinguished from predictable pharmacologic side effects.","source":"Pharmacology"},{"id":"mc-0296","title":"QT prolongation","category":"Pharmacology","level":"Clinical","fact":"Some drugs delay ventricular repolarization, increasing torsades risk especially with electrolyte disturbance.","source":"Pharmacology"},{"id":"mc-0297","title":"Serotonin toxicity","category":"Pharmacology","level":"Clinical","fact":"Excess serotonergic activity may cause autonomic instability, neuromuscular hyperactivity and altered mental state.","source":"Pharmacology"},{"id":"mc-0298","title":"Anticholinergic burden","category":"Pharmacology","level":"Clinical","fact":"Multiple antimuscarinic drugs can worsen dry mouth, urinary retention, delirium and constipation.","source":"Pharmacology"},{"id":"mc-0299","title":"Opioid respiratory depression","category":"Pharmacology","level":"Clinical","fact":"Opioids can suppress brainstem respiratory drive; risk rises with sedatives and frailty.","source":"Pharmacology"},{"id":"mc-0300","title":"NSAID renal effects","category":"Pharmacology","level":"Clinical","fact":"NSAIDs reduce prostaglandin synthesis and may impair renal perfusion in susceptible patients.","source":"Pharmacology"},{"id":"mc-0301","title":"Paracetamol toxicity","category":"Pharmacology","level":"Clinical","fact":"Acetaminophen overdose can deplete protective glutathione and cause severe hepatic injury.","source":"Pharmacology"},{"id":"mc-0302","title":"Aspirin antiplatelet action","category":"Pharmacology","level":"Clinical","fact":"Aspirin irreversibly inhibits platelet COX-1, reducing thromboxane production for the platelet lifespan.","source":"Pharmacology"},{"id":"mc-0303","title":"P2Y12 inhibitors","category":"Pharmacology","level":"Clinical","fact":"Clopidogrel and related agents suppress ADP-mediated platelet activation but differ in metabolism and interactions.","source":"Pharmacology"},{"id":"mc-0304","title":"Unfractionated heparin","category":"Pharmacology","level":"Clinical","fact":"Heparin enhances antithrombin activity and requires bleeding-risk and monitoring considerations.","source":"Pharmacology"},{"id":"mc-0305","title":"Low-molecular-weight heparin","category":"Pharmacology","level":"Clinical","fact":"LMWH has relatively predictable anticoagulant effects, though renal function and weight may matter.","source":"Pharmacology"},{"id":"mc-0306","title":"Warfarin mechanism","category":"Pharmacology","level":"Clinical","fact":"Warfarin reduces activation of vitamin K–dependent clotting factors, requiring INR-based management.","source":"Pharmacology"},{"id":"mc-0307","title":"Direct oral anticoagulants","category":"Pharmacology","level":"Clinical","fact":"DOACs act on factor Xa or thrombin and have agent-specific kidney, interaction and procedural considerations.","source":"Pharmacology"},{"id":"mc-0308","title":"ACE inhibitor mechanism","category":"Pharmacology","level":"Clinical","fact":"ACE inhibitors reduce angiotensin II formation and may cause cough, hyperkalemia or creatinine change.","source":"Pharmacology"},{"id":"mc-0309","title":"Angiotensin receptor blockers","category":"Pharmacology","level":"Clinical","fact":"ARBs block angiotensin II AT1 signaling without directly inhibiting ACE-mediated bradykinin degradation.","source":"Pharmacology"},{"id":"mc-0310","title":"Beta blockers","category":"Pharmacology","level":"Clinical","fact":"Beta blockers reduce beta-adrenergic effects; selectivity, indications and contraindications differ among agents.","source":"Pharmacology"},{"id":"mc-0311","title":"Dihydropyridine calcium blockers","category":"Pharmacology","level":"Clinical","fact":"Agents such as amlodipine primarily relax vascular smooth muscle and can cause peripheral edema.","source":"Pharmacology"},{"id":"mc-0312","title":"Non-dihydropyridine calcium blockers","category":"Pharmacology","level":"Clinical","fact":"Verapamil and diltiazem slow AV-nodal conduction and have important interaction and cardiac cautions.","source":"Pharmacology"},{"id":"mc-0313","title":"Loop diuretics","category":"Pharmacology","level":"Clinical","fact":"Loop diuretics inhibit NKCC2 in the thick ascending limb and can cause electrolyte losses.","source":"Pharmacology"},{"id":"mc-0314","title":"Thiazide-type diuretics","category":"Pharmacology","level":"Clinical","fact":"Thiazides inhibit distal tubular sodium–chloride transport and can lower serum sodium or potassium.","source":"Pharmacology"},{"id":"mc-0315","title":"Potassium-sparing diuretics","category":"Pharmacology","level":"Clinical","fact":"Mineralocorticoid antagonists and epithelial sodium-channel blockers may increase serum potassium.","source":"Pharmacology"},{"id":"mc-0316","title":"Statins","category":"Pharmacology","level":"Clinical","fact":"Statins inhibit HMG-CoA reductase and reduce hepatic cholesterol synthesis with increased LDL receptor activity.","source":"Pharmacology"},{"id":"mc-0317","title":"Ezetimibe","category":"Pharmacology","level":"Clinical","fact":"Ezetimibe inhibits intestinal cholesterol absorption via NPC1L1.","source":"Pharmacology"},{"id":"mc-0318","title":"SGLT2 inhibitors","category":"Pharmacology","level":"Clinical","fact":"SGLT2 inhibitors reduce renal glucose reabsorption and have indications beyond glucose control for selected patients.","source":"Pharmacology"},{"id":"mc-0319","title":"Metformin","category":"Pharmacology","level":"Clinical","fact":"Metformin reduces hepatic glucose production and improves insulin sensitivity; kidney function and illness status affect safe use.","source":"Pharmacology"},{"id":"mc-0320","title":"Sulfonylureas","category":"Pharmacology","level":"Clinical","fact":"Sulfonylureas increase pancreatic insulin secretion and can cause hypoglycemia.","source":"Pharmacology"},{"id":"mc-0321","title":"GLP-1 receptor agonists","category":"Pharmacology","level":"Clinical","fact":"GLP-1 receptor agonists augment glucose-dependent insulin secretion and slow gastric emptying to varying degrees.","source":"Pharmacology"},{"id":"mc-0322","title":"Insulin types","category":"Pharmacology","level":"Clinical","fact":"Rapid, short, intermediate and long-acting insulin preparations differ in onset, duration and clinical roles.","source":"Pharmacology"},{"id":"mc-0323","title":"Glucocorticoid adverse effects","category":"Pharmacology","level":"Clinical","fact":"Systemic steroids can cause hyperglycemia, infection risk, mood effects and adrenal suppression.","source":"Pharmacology"},{"id":"mc-0324","title":"Levothyroxine","category":"Pharmacology","level":"Clinical","fact":"Levothyroxine replaces thyroid hormone; absorption varies with food and some supplements or medications.","source":"Pharmacology"},{"id":"mc-0325","title":"Proton pump inhibitors","category":"Pharmacology","level":"Clinical","fact":"PPIs inhibit gastric H+/K+-ATPase and strongly suppress acid secretion.","source":"Pharmacology"},{"id":"mc-0326","title":"H2 receptor antagonists","category":"Pharmacology","level":"Clinical","fact":"H2 blockers reduce histamine-driven gastric acid secretion and have renal considerations for some agents.","source":"Pharmacology"},{"id":"mc-0327","title":"Antiemetic 5-HT3 antagonists","category":"Pharmacology","level":"Clinical","fact":"Ondansetron and related agents block serotonin 5-HT3 receptors and can affect cardiac repolarization.","source":"Pharmacology"},{"id":"mc-0328","title":"Beta-2 agonists","category":"Pharmacology","level":"Clinical","fact":"Inhaled beta-2 agonists relax bronchial smooth muscle; systemic effects may include tremor and tachycardia.","source":"Pharmacology"},{"id":"mc-0329","title":"Inhaled corticosteroids","category":"Pharmacology","level":"Clinical","fact":"Inhaled steroids suppress airway inflammation but are not interchangeable with rapid reliever bronchodilation.","source":"Pharmacology"},{"id":"mc-0330","title":"Antimuscarinic inhalers","category":"Pharmacology","level":"Clinical","fact":"Inhaled muscarinic antagonists reduce cholinergic bronchoconstriction; duration differs by agent.","source":"Pharmacology"},{"id":"mc-0331","title":"Penicillin antibiotics","category":"Pharmacology","level":"Clinical","fact":"Penicillins inhibit bacterial cell-wall transpeptidation; spectrum and beta-lactamase stability vary widely.","source":"Pharmacology"},{"id":"mc-0332","title":"Cephalosporins","category":"Pharmacology","level":"Clinical","fact":"Cephalosporins are beta-lactams with generation-dependent activity and varying organism coverage.","source":"Pharmacology"},{"id":"mc-0333","title":"Carbapenems","category":"Pharmacology","level":"Clinical","fact":"Carbapenems have broad beta-lactam activity but resistance and stewardship concerns remain essential.","source":"Pharmacology"},{"id":"mc-0334","title":"Macrolides","category":"Pharmacology","level":"Clinical","fact":"Macrolides inhibit bacterial protein synthesis at the 50S ribosome and can cause QT or interaction issues.","source":"Pharmacology"},{"id":"mc-0335","title":"Tetracyclines","category":"Pharmacology","level":"Clinical","fact":"Tetracyclines bind the 30S ribosome and can have chelation interactions with calcium and iron.","source":"Pharmacology"},{"id":"mc-0336","title":"Aminoglycosides","category":"Pharmacology","level":"Clinical","fact":"Aminoglycosides target the 30S ribosome and have nephrotoxic and ototoxic risk.","source":"Pharmacology"},{"id":"mc-0337","title":"Fluoroquinolones","category":"Pharmacology","level":"Clinical","fact":"Fluoroquinolones inhibit bacterial topoisomerases and have important tendon, neurologic and safety warnings.","source":"Pharmacology"},{"id":"mc-0338","title":"Trimethoprim–sulfamethoxazole","category":"Pharmacology","level":"Clinical","fact":"This combination inhibits sequential folate pathway steps and has allergy and hyperkalemia considerations.","source":"Pharmacology"},{"id":"mc-0339","title":"Vancomycin","category":"Pharmacology","level":"Clinical","fact":"Vancomycin inhibits gram-positive cell-wall synthesis; IV exposure and renal monitoring affect toxicity management.","source":"Pharmacology"},{"id":"mc-0340","title":"Metronidazole","category":"Pharmacology","level":"Clinical","fact":"Metronidazole is active against many anaerobes and certain protozoa through reductive activation.","source":"Pharmacology"},{"id":"mc-0341","title":"Antifungal azoles","category":"Pharmacology","level":"Clinical","fact":"Azoles inhibit fungal ergosterol synthesis and vary substantially in interactions and spectrum.","source":"Pharmacology"},{"id":"mc-0342","title":"Acyclovir","category":"Pharmacology","level":"Clinical","fact":"Acyclovir inhibits herpesvirus DNA polymerase after activation by viral enzymes in susceptible viruses.","source":"Pharmacology"},{"id":"mc-0343","title":"Antiretroviral therapy","category":"Pharmacology","level":"Clinical","fact":"Combination antiretroviral therapy targets different HIV replication steps to suppress viral load and resistance.","source":"Pharmacology"},{"id":"mc-0344","title":"Antiseizure drug interactions","category":"Pharmacology","level":"Clinical","fact":"Enzyme-inducing antiseizure drugs can alter contraceptive and other medicine exposures.","source":"Pharmacology"},{"id":"mc-0345","title":"SSRIs","category":"Pharmacology","level":"Clinical","fact":"Selective serotonin reuptake inhibitors inhibit serotonin transporters; responses and adverse effects vary over weeks.","source":"Pharmacology"},{"id":"mc-0346","title":"Benzodiazepines","category":"Pharmacology","level":"Clinical","fact":"Benzodiazepines potentiate GABA-A receptor activity and can cause dependence and respiratory compromise with other depressants.","source":"Pharmacology"},{"id":"mc-0347","title":"Antipsychotics","category":"Pharmacology","level":"Clinical","fact":"Antipsychotics affect dopamine signaling and vary in metabolic, extrapyramidal and prolactin effects.","source":"Pharmacology"},{"id":"mc-0348","title":"Local anesthetics","category":"Pharmacology","level":"Clinical","fact":"Local anesthetics block voltage-gated sodium channels; systemic toxicity can affect nervous and cardiac tissues.","source":"Pharmacology"},{"id":"mc-0349","title":"Neuromuscular blockers","category":"Pharmacology","level":"Clinical","fact":"Paralytic agents block neuromuscular transmission but do not themselves provide sedation or analgesia.","source":"Pharmacology"},{"id":"mc-0350","title":"Vaccines","category":"Pharmacology","level":"Clinical","fact":"Vaccine safety and indications depend on age, pregnancy, immunocompromise, product and local schedule.","source":"Pharmacology"},{"id":"mc-0351","title":"Antibiotic stewardship","category":"Pharmacology","level":"Clinical","fact":"Choose antimicrobials only for justified indications, using likely pathogens, site, cultures and local resistance data.","source":"Pharmacology"},{"id":"mc-0352","title":"High-alert medications","category":"Pharmacology","level":"Clinical","fact":"Insulin, anticoagulants and concentrated electrolytes often require enhanced handling due to severe harm potential.","source":"Pharmacology"},{"id":"mc-0353","title":"Complete blood count","category":"Diagnostics & Interpretation","level":"Clinical","fact":"CBC reports red cells, white cells and platelets; interpret abnormalities with indices and clinical context.","source":"Diagnostics & Interpretation"},{"id":"mc-0354","title":"Hemoglobin","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Hemoglobin indicates blood oxygen-carrying capacity but may initially appear normal after acute hemorrhage.","source":"Diagnostics & Interpretation"},{"id":"mc-0355","title":"Hematocrit","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Hematocrit is the proportion of blood volume occupied by red cells and changes with hydration and cell size.","source":"Diagnostics & Interpretation"},{"id":"mc-0356","title":"Mean corpuscular volume","category":"Diagnostics & Interpretation","level":"Clinical","fact":"MCV describes average erythrocyte volume, supporting microcytic, normocytic and macrocytic anemia classification.","source":"Diagnostics & Interpretation"},{"id":"mc-0357","title":"Reticulocyte count","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Reticulocytes indicate marrow red-cell production; adjust interpretation for anemia severity.","source":"Diagnostics & Interpretation"},{"id":"mc-0358","title":"Red-cell distribution width","category":"Diagnostics & Interpretation","level":"Clinical","fact":"RDW reflects variation in erythrocyte size and may help characterize mixed anemia populations.","source":"Diagnostics & Interpretation"},{"id":"mc-0359","title":"Peripheral smear","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Blood film morphology can reveal blasts, schistocytes, spherocytes and other clues missed by numerical counts.","source":"Diagnostics & Interpretation"},{"id":"mc-0360","title":"Platelet count","category":"Diagnostics & Interpretation","level":"Clinical","fact":"A low platelet count should prompt review for true thrombocytopenia, clumping and clinical bleeding risk.","source":"Diagnostics & Interpretation"},{"id":"mc-0361","title":"Neutrophil count","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Absolute neutrophil count better estimates neutropenia than total white-cell count alone.","source":"Diagnostics & Interpretation"},{"id":"mc-0362","title":"Ferritin","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Ferritin reflects iron stores but also rises as an acute-phase reactant during inflammation.","source":"Diagnostics & Interpretation"},{"id":"mc-0363","title":"Transferrin saturation","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Transferrin saturation assesses circulating iron availability alongside ferritin and inflammatory context.","source":"Diagnostics & Interpretation"},{"id":"mc-0364","title":"Vitamin B12 testing","category":"Diagnostics & Interpretation","level":"Clinical","fact":"A borderline B12 concentration may require additional testing and clinical correlation, particularly with neurologic symptoms.","source":"Diagnostics & Interpretation"},{"id":"mc-0365","title":"Folate testing","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Folate deficiency can contribute to macrocytosis; neurologic findings should raise concern for concomitant B12 deficiency.","source":"Diagnostics & Interpretation"},{"id":"mc-0366","title":"Prothrombin time INR","category":"Diagnostics & Interpretation","level":"Clinical","fact":"PT/INR assesses the extrinsic and common coagulation pathways and monitors vitamin K antagonist therapy.","source":"Diagnostics & Interpretation"},{"id":"mc-0367","title":"Activated partial thromboplastin time","category":"Diagnostics & Interpretation","level":"Clinical","fact":"aPTT examines intrinsic and common pathway factors and is affected by heparin and inhibitors.","source":"Diagnostics & Interpretation"},{"id":"mc-0368","title":"Fibrinogen","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Fibrinogen is an acute-phase reactant but may become low in consumption or severe liver dysfunction.","source":"Diagnostics & Interpretation"},{"id":"mc-0369","title":"D-dimer","category":"Diagnostics & Interpretation","level":"Clinical","fact":"D-dimer is sensitive but nonspecific for fibrin turnover; usefulness depends on pretest probability and assay.","source":"Diagnostics & Interpretation"},{"id":"mc-0370","title":"C-reactive protein","category":"Diagnostics & Interpretation","level":"Clinical","fact":"CRP indicates inflammation but cannot independently distinguish bacterial infection from other causes.","source":"Diagnostics & Interpretation"},{"id":"mc-0371","title":"ESR","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Erythrocyte sedimentation rate is influenced by inflammatory proteins, anemia and patient characteristics.","source":"Diagnostics & Interpretation"},{"id":"mc-0372","title":"Procalcitonin","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Procalcitonin may aid selected infection assessments but must not replace clinical evaluation or source control.","source":"Diagnostics & Interpretation"},{"id":"mc-0373","title":"Serum creatinine","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Creatinine is influenced by muscle mass and can lag behind acute changes in kidney function.","source":"Diagnostics & Interpretation"},{"id":"mc-0374","title":"Estimated GFR","category":"Diagnostics & Interpretation","level":"Clinical","fact":"eGFR estimates filtration from biomarkers and patient factors; it is less reliable during rapidly changing renal function.","source":"Diagnostics & Interpretation"},{"id":"mc-0375","title":"Blood urea nitrogen","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Urea changes with filtration, hydration, catabolism and gastrointestinal bleeding; it is not kidney-specific.","source":"Diagnostics & Interpretation"},{"id":"mc-0376","title":"Sodium measurement","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Serum sodium reflects water balance relative to sodium rather than total body sodium alone.","source":"Diagnostics & Interpretation"},{"id":"mc-0377","title":"Potassium measurement","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Potassium abnormalities can alter cardiac conduction; hemolysis may produce falsely high results.","source":"Diagnostics & Interpretation"},{"id":"mc-0378","title":"Chloride and bicarbonate","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Chloride and total CO2 help categorize acid–base and electrolyte disturbances.","source":"Diagnostics & Interpretation"},{"id":"mc-0379","title":"Anion gap","category":"Diagnostics & Interpretation","level":"Clinical","fact":"The anion gap helps identify unmeasured ions in metabolic acidosis; albumin affects its expected value.","source":"Diagnostics & Interpretation"},{"id":"mc-0380","title":"Serum osmolality","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Measured osmolality helps evaluate hyponatremia, toxic alcohols and hyperosmolar states.","source":"Diagnostics & Interpretation"},{"id":"mc-0381","title":"Urine osmolality","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Urine osmolality indicates renal concentration or dilution response to water balance.","source":"Diagnostics & Interpretation"},{"id":"mc-0382","title":"Urine sodium","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Urine sodium can help assess renal sodium handling but is confounded by diuretics and kidney disease.","source":"Diagnostics & Interpretation"},{"id":"mc-0383","title":"Urinalysis dipstick","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Dipstick detects selected urinary analytes; confirm relevant findings with microscopy or culture when indicated.","source":"Diagnostics & Interpretation"},{"id":"mc-0384","title":"Urine microscopy","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Red-cell casts suggest glomerular inflammation, while white-cell casts may indicate renal parenchymal inflammation.","source":"Diagnostics & Interpretation"},{"id":"mc-0385","title":"Albumin–creatinine ratio","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Urinary ACR detects and stages albuminuria when combined with eGFR and clinical findings.","source":"Diagnostics & Interpretation"},{"id":"mc-0386","title":"Liver transaminases","category":"Diagnostics & Interpretation","level":"Clinical","fact":"ALT and AST indicate hepatocellular injury, but magnitude does not directly indicate liver synthetic function.","source":"Diagnostics & Interpretation"},{"id":"mc-0387","title":"Alkaline phosphatase","category":"Diagnostics & Interpretation","level":"Clinical","fact":"ALP rises in cholestasis and bone turnover; GGT or isoenzymes can help identify origin.","source":"Diagnostics & Interpretation"},{"id":"mc-0388","title":"Gamma-glutamyl transferase","category":"Diagnostics & Interpretation","level":"Clinical","fact":"GGT supports a hepatic source of elevated ALP but is sensitive to medications and alcohol use.","source":"Diagnostics & Interpretation"},{"id":"mc-0389","title":"Bilirubin fractionation","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Conjugated and unconjugated bilirubin patterns help localize causes of jaundice.","source":"Diagnostics & Interpretation"},{"id":"mc-0390","title":"Serum albumin","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Albumin reflects several influences including inflammation, loss, nutrition and liver synthesis over time.","source":"Diagnostics & Interpretation"},{"id":"mc-0391","title":"Cardiac troponin","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Troponin indicates myocardial injury; infarction also requires evidence of ischemia and clinical context.","source":"Diagnostics & Interpretation"},{"id":"mc-0392","title":"BNP and NT-proBNP","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Natriuretic peptides support heart-failure assessment but vary with age, obesity and kidney function.","source":"Diagnostics & Interpretation"},{"id":"mc-0393","title":"Creatine kinase","category":"Diagnostics & Interpretation","level":"Clinical","fact":"CK rises with skeletal muscle injury and can aid assessment of rhabdomyolysis.","source":"Diagnostics & Interpretation"},{"id":"mc-0394","title":"Thyroid-stimulating hormone","category":"Diagnostics & Interpretation","level":"Clinical","fact":"TSH is a sensitive primary-thyroid screening test but can mislead in pituitary or acute illness.","source":"Diagnostics & Interpretation"},{"id":"mc-0395","title":"Free thyroxine","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Free T4 helps characterize thyroid status when paired with TSH and the clinical scenario.","source":"Diagnostics & Interpretation"},{"id":"mc-0396","title":"HbA1c","category":"Diagnostics & Interpretation","level":"Clinical","fact":"HbA1c estimates average glycemia over months but may misrepresent it when red-cell survival changes.","source":"Diagnostics & Interpretation"},{"id":"mc-0397","title":"Fasting plasma glucose","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Fasting glucose supports diabetes assessment but results depend on proper preparation and repeat criteria.","source":"Diagnostics & Interpretation"},{"id":"mc-0398","title":"Oral glucose tolerance test","category":"Diagnostics & Interpretation","level":"Clinical","fact":"The OGTT evaluates glucose handling and has specific indications and preparation requirements.","source":"Diagnostics & Interpretation"},{"id":"mc-0399","title":"Serum cortisol","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Cortisol varies with time of day and stress; interpretation depends on sampling and clinical question.","source":"Diagnostics & Interpretation"},{"id":"mc-0400","title":"ACTH stimulation test","category":"Diagnostics & Interpretation","level":"Clinical","fact":"ACTH stimulation evaluates adrenal cortisol reserve in selected suspected insufficiency cases.","source":"Diagnostics & Interpretation"},{"id":"mc-0401","title":"Parathyroid hormone","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Interpret PTH with simultaneous calcium, vitamin D status and kidney function.","source":"Diagnostics & Interpretation"},{"id":"mc-0402","title":"Vitamin D level","category":"Diagnostics & Interpretation","level":"Clinical","fact":"25-hydroxyvitamin D is the conventional marker of vitamin D stores rather than active 1,25-dihydroxyvitamin D.","source":"Diagnostics & Interpretation"},{"id":"mc-0403","title":"Arterial blood gas","category":"Diagnostics & Interpretation","level":"Clinical","fact":"An ABG measures pH, arterial gases and acid–base components; sampling and oxygen conditions matter.","source":"Diagnostics & Interpretation"},{"id":"mc-0404","title":"Venous blood gas","category":"Diagnostics & Interpretation","level":"Clinical","fact":"VBG can aid acid–base assessment but does not substitute for arterial oxygenation measurement.","source":"Diagnostics & Interpretation"},{"id":"mc-0405","title":"Lactate","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Raised lactate may indicate impaired metabolism or clearance and is not specific for tissue hypoxia alone.","source":"Diagnostics & Interpretation"},{"id":"mc-0406","title":"Pulse oximetry","category":"Diagnostics & Interpretation","level":"Clinical","fact":"SpO2 estimates arterial oxygen saturation but can be inaccurate with poor perfusion, dyshemoglobins or other factors.","source":"Diagnostics & Interpretation"},{"id":"mc-0407","title":"Capnography","category":"Diagnostics & Interpretation","level":"Clinical","fact":"End-tidal CO2 supports ventilation and airway monitoring, though it can differ substantially from arterial CO2.","source":"Diagnostics & Interpretation"},{"id":"mc-0408","title":"Chest radiograph","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Systematic CXR review checks projection, airway, bones, cardiac silhouette, diaphragms and lung fields.","source":"Diagnostics & Interpretation"},{"id":"mc-0409","title":"Pneumothorax imaging","category":"Diagnostics & Interpretation","level":"Clinical","fact":"A pleural line without peripheral lung markings supports pneumothorax, but subtle films need careful review.","source":"Diagnostics & Interpretation"},{"id":"mc-0410","title":"Pleural effusion imaging","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Blunted costophrenic angles and dependent opacity can suggest pleural fluid; ultrasound may improve detection.","source":"Diagnostics & Interpretation"},{"id":"mc-0411","title":"ECG rate and rhythm","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Start ECG interpretation with rate, regularity, P waves, QRS width and intervals.","source":"Diagnostics & Interpretation"},{"id":"mc-0412","title":"ECG axis","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Frontal-plane QRS axis provides clues to conduction, ventricular loading and anatomical variation.","source":"Diagnostics & Interpretation"},{"id":"mc-0413","title":"PR interval","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Prolonged PR indicates delayed atrioventricular conduction, with different degrees of block requiring separate assessment.","source":"Diagnostics & Interpretation"},{"id":"mc-0414","title":"QRS duration","category":"Diagnostics & Interpretation","level":"Clinical","fact":"A broad QRS may reflect bundle branch block, ventricular rhythm or metabolic and drug effects.","source":"Diagnostics & Interpretation"},{"id":"mc-0415","title":"QT interval","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Correct QT for heart rate and assess relevant medications and electrolytes when prolonged.","source":"Diagnostics & Interpretation"},{"id":"mc-0416","title":"ST elevation","category":"Diagnostics & Interpretation","level":"Clinical","fact":"ST elevation has multiple causes; myocardial ischemia interpretation depends on territory, symptoms and serial changes.","source":"Diagnostics & Interpretation"},{"id":"mc-0417","title":"T-wave inversion","category":"Diagnostics & Interpretation","level":"Clinical","fact":"T-wave inversion may reflect ischemia, strain or normal variants depending on leads and context.","source":"Diagnostics & Interpretation"},{"id":"mc-0418","title":"Echocardiography","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Echo evaluates cardiac structure, function and hemodynamics, but limitations depend on acoustic windows and technique.","source":"Diagnostics & Interpretation"},{"id":"mc-0419","title":"Ultrasound FAST","category":"Diagnostics & Interpretation","level":"Clinical","fact":"FAST identifies free intraperitoneal or pericardial fluid in trauma but a negative scan does not exclude injury.","source":"Diagnostics & Interpretation"},{"id":"mc-0420","title":"CT radiation","category":"Diagnostics & Interpretation","level":"Clinical","fact":"CT uses ionizing radiation; clinical benefit, contrast risks and alternatives should be weighed.","source":"Diagnostics & Interpretation"},{"id":"mc-0421","title":"MRI contraindications","category":"Diagnostics & Interpretation","level":"Clinical","fact":"MRI safety requires careful screening for implants, metal and device compatibility.","source":"Diagnostics & Interpretation"},{"id":"mc-0422","title":"Contrast-associated kidney risk","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Kidney risk after contrast varies with clinical setting and baseline renal function; avoid blanket assumptions.","source":"Diagnostics & Interpretation"},{"id":"mc-0423","title":"CSF analysis","category":"Diagnostics & Interpretation","level":"Clinical","fact":"CSF cell count, glucose, protein and microbiology help assess CNS infection but patterns overlap.","source":"Diagnostics & Interpretation"},{"id":"mc-0424","title":"Lumbar puncture safety","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Imaging or deferral may be needed when signs suggest elevated intracranial pressure, focal lesions or bleeding risk.","source":"Diagnostics & Interpretation"},{"id":"mc-0425","title":"Blood culture collection","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Collect blood cultures with aseptic technique and appropriate timing when bacteremia is suspected.","source":"Diagnostics & Interpretation"},{"id":"mc-0426","title":"Sputum specimen quality","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Poor-quality sputum contaminated with oral flora can mislead microbiologic interpretation.","source":"Diagnostics & Interpretation"},{"id":"mc-0427","title":"Urine culture","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Culture results should be interpreted alongside urinary symptoms; bacteriuria alone is not always infection.","source":"Diagnostics & Interpretation"},{"id":"mc-0428","title":"Pregnancy test","category":"Diagnostics & Interpretation","level":"Clinical","fact":"Pregnancy status alters differential diagnosis and imaging or medication choices in reproductive-age patients.","source":"Diagnostics & Interpretation"},{"id":"mc-0429","title":"Acute coronary syndrome","category":"Clinical Medicine","level":"Clinical","fact":"Ischemic chest discomfort with ECG change or troponin rise prompts rapid assessment using appropriate pathways.","source":"Clinical Medicine"},{"id":"mc-0430","title":"Stable angina","category":"Clinical Medicine","level":"Clinical","fact":"Exertional chest pressure relieved by rest suggests myocardial ischemia but has important alternative explanations.","source":"Clinical Medicine"},{"id":"mc-0431","title":"Aortic dissection","category":"Clinical Medicine","level":"Clinical","fact":"Abrupt severe chest or back pain with neurological or pulse findings raises concern for aortic dissection.","source":"Clinical Medicine"},{"id":"mc-0432","title":"Pericarditis","category":"Clinical Medicine","level":"Clinical","fact":"Pleuritic or positional chest pain with characteristic ECG changes can suggest pericardial inflammation.","source":"Clinical Medicine"},{"id":"mc-0433","title":"Cardiac tamponade","category":"Clinical Medicine","level":"Clinical","fact":"Pericardial pressure can impair ventricular filling and cause obstructive shock requiring urgent specialist assessment.","source":"Clinical Medicine"},{"id":"mc-0434","title":"Aortic stenosis","category":"Clinical Medicine","level":"Clinical","fact":"Exertional syncope, angina and dyspnea with an ejection systolic murmur suggest significant aortic stenosis.","source":"Clinical Medicine"},{"id":"mc-0435","title":"Mitral regurgitation","category":"Clinical Medicine","level":"Clinical","fact":"A pansystolic apical murmur radiating to the axilla may indicate mitral regurgitation.","source":"Clinical Medicine"},{"id":"mc-0436","title":"Atrial fibrillation","category":"Clinical Medicine","level":"Clinical","fact":"AF produces irregularly irregular ventricular rhythm and requires assessment of causes, symptoms and stroke risk.","source":"Clinical Medicine"},{"id":"mc-0437","title":"Supraventricular tachycardia","category":"Clinical Medicine","level":"Clinical","fact":"Regular narrow-complex tachycardia can arise from AV nodal or accessory-pathway reentry.","source":"Clinical Medicine"},{"id":"mc-0438","title":"Ventricular tachycardia","category":"Clinical Medicine","level":"Clinical","fact":"Broad-complex tachycardia should be treated as potentially ventricular until appropriately assessed.","source":"Clinical Medicine"},{"id":"mc-0439","title":"Infective endocarditis","category":"Clinical Medicine","level":"Clinical","fact":"Fever with a new murmur, vascular phenomena or positive cultures should prompt assessment for endocardial infection.","source":"Clinical Medicine"},{"id":"mc-0440","title":"Heart failure syndrome","category":"Clinical Medicine","level":"Clinical","fact":"Breathlessness, edema and fatigue may reflect elevated filling pressure or poor perfusion from structural or functional heart disease.","source":"Clinical Medicine"},{"id":"mc-0441","title":"Hypertensive emergency","category":"Clinical Medicine","level":"Clinical","fact":"Severely elevated blood pressure with acute target-organ injury differs from isolated asymptomatic high readings.","source":"Clinical Medicine"},{"id":"mc-0442","title":"Deep vein thrombosis","category":"Clinical Medicine","level":"Clinical","fact":"Unilateral leg swelling and pain require pretest-probability assessment before tests are chosen.","source":"Clinical Medicine"},{"id":"mc-0443","title":"Pulmonary embolism","category":"Clinical Medicine","level":"Clinical","fact":"PE may cause sudden dyspnea, pleuritic pain, tachycardia or syncope, with variable examination findings.","source":"Clinical Medicine"},{"id":"mc-0444","title":"Community-acquired pneumonia","category":"Clinical Medicine","level":"Clinical","fact":"Fever, cough, breathlessness and focal signs can support pneumonia, but diagnosis depends on severity and setting.","source":"Clinical Medicine"},{"id":"mc-0445","title":"Asthma exacerbation","category":"Clinical Medicine","level":"Clinical","fact":"Airway inflammation and variable airflow obstruction cause wheeze and dyspnea; a silent chest can signal danger.","source":"Clinical Medicine"},{"id":"mc-0446","title":"COPD exacerbation","category":"Clinical Medicine","level":"Clinical","fact":"Worsening breathlessness, sputum and cough in COPD can reflect infection or noninfectious triggers.","source":"Clinical Medicine"},{"id":"mc-0447","title":"Tension pneumothorax","category":"Clinical Medicine","level":"Clinical","fact":"Hemodynamic compromise with suspected pneumothorax is a time-critical clinical diagnosis.","source":"Clinical Medicine"},{"id":"mc-0448","title":"Pleural effusion","category":"Clinical Medicine","level":"Clinical","fact":"Fluid accumulates between pleural layers from cardiac, inflammatory, malignant or other causes.","source":"Clinical Medicine"},{"id":"mc-0449","title":"Pulmonary edema","category":"Clinical Medicine","level":"Clinical","fact":"Acute pulmonary edema produces breathlessness and diffuse lung fluid, often due to cardiac dysfunction.","source":"Clinical Medicine"},{"id":"mc-0450","title":"Interstitial lung disease","category":"Clinical Medicine","level":"Clinical","fact":"Progressive exertional dyspnea with inspiratory crackles may indicate diffuse parenchymal lung disease.","source":"Clinical Medicine"},{"id":"mc-0451","title":"Obstructive sleep apnea","category":"Clinical Medicine","level":"Clinical","fact":"Repeated sleep-related upper-airway obstruction contributes to daytime sleepiness and cardiometabolic risk.","source":"Clinical Medicine"},{"id":"mc-0452","title":"Acute kidney injury","category":"Clinical Medicine","level":"Clinical","fact":"AKI is a rise in creatinine and/or reduction in urine output requiring assessment of volume, obstruction and exposures.","source":"Clinical Medicine"},{"id":"mc-0453","title":"Chronic kidney disease","category":"Clinical Medicine","level":"Clinical","fact":"CKD requires persistent abnormalities of kidney structure or function, usually over at least three months.","source":"Clinical Medicine"},{"id":"mc-0454","title":"Hyperkalemia","category":"Clinical Medicine","level":"Clinical","fact":"High potassium can provoke malignant arrhythmia; assess ECG, renal function and potential specimen artifact.","source":"Clinical Medicine"},{"id":"mc-0455","title":"Hyponatremia","category":"Clinical Medicine","level":"Clinical","fact":"Low sodium requires evaluation of tonicity, symptoms, chronicity and urine concentrating responses.","source":"Clinical Medicine"},{"id":"mc-0456","title":"Nephrolithiasis","category":"Clinical Medicine","level":"Clinical","fact":"Renal colic often causes severe flank pain radiating toward the groin with possible hematuria.","source":"Clinical Medicine"},{"id":"mc-0457","title":"Pyelonephritis","category":"Clinical Medicine","level":"Clinical","fact":"Fever, flank pain and urinary symptoms can indicate upper urinary tract infection.","source":"Clinical Medicine"},{"id":"mc-0458","title":"Glomerulonephritis syndrome","category":"Clinical Medicine","level":"Clinical","fact":"Hematuria with proteinuria, casts, edema or hypertension suggests glomerular pathology.","source":"Clinical Medicine"},{"id":"mc-0459","title":"DKA","category":"Clinical Medicine","level":"Clinical","fact":"Diabetic ketoacidosis involves ketogenesis, metabolic acidosis and variable hyperglycemia after insulin deficiency.","source":"Clinical Medicine"},{"id":"mc-0460","title":"Hyperosmolar hyperglycemic state","category":"Clinical Medicine","level":"Clinical","fact":"HHS involves severe hyperglycemia and hyperosmolality with less prominent ketosis than DKA.","source":"Clinical Medicine"},{"id":"mc-0461","title":"Hypoglycemia","category":"Clinical Medicine","level":"Clinical","fact":"Low glucose can cause autonomic and neuroglycopenic symptoms and is especially dangerous with impaired awareness.","source":"Clinical Medicine"},{"id":"mc-0462","title":"Hypothyroidism","category":"Clinical Medicine","level":"Clinical","fact":"Fatigue, cold intolerance, constipation and bradycardia may suggest deficient thyroid hormone action.","source":"Clinical Medicine"},{"id":"mc-0463","title":"Thyrotoxicosis","category":"Clinical Medicine","level":"Clinical","fact":"Weight loss, tremor, heat intolerance and tachycardia can reflect excess thyroid hormone effect.","source":"Clinical Medicine"},{"id":"mc-0464","title":"Adrenal crisis","category":"Clinical Medicine","level":"Clinical","fact":"Acute adrenal insufficiency may cause hypotension, gastrointestinal symptoms and electrolyte derangements.","source":"Clinical Medicine"},{"id":"mc-0465","title":"Cushing syndrome","category":"Clinical Medicine","level":"Clinical","fact":"Chronic glucocorticoid excess may produce proximal weakness, easy bruising and metabolic complications.","source":"Clinical Medicine"},{"id":"mc-0466","title":"Primary hyperparathyroidism","category":"Clinical Medicine","level":"Clinical","fact":"Elevated calcium with inappropriately non-suppressed PTH suggests primary hyperparathyroidism.","source":"Clinical Medicine"},{"id":"mc-0467","title":"Upper GI bleeding","category":"Clinical Medicine","level":"Clinical","fact":"Hematemesis or melena can indicate upper gastrointestinal hemorrhage; circulation and risk assessment are priorities.","source":"Clinical Medicine"},{"id":"mc-0468","title":"Acute cholecystitis","category":"Clinical Medicine","level":"Clinical","fact":"Right upper quadrant pain with fever and localized tenderness may reflect gallbladder inflammation.","source":"Clinical Medicine"},{"id":"mc-0469","title":"Acute cholangitis","category":"Clinical Medicine","level":"Clinical","fact":"Fever, jaundice and upper abdominal pain suggest biliary infection and possible obstruction.","source":"Clinical Medicine"},{"id":"mc-0470","title":"Acute pancreatitis","category":"Clinical Medicine","level":"Clinical","fact":"Typical epigastric pain radiating to back with enzyme elevation or characteristic imaging supports pancreatitis.","source":"Clinical Medicine"},{"id":"mc-0471","title":"Bowel obstruction","category":"Clinical Medicine","level":"Clinical","fact":"Colicky pain, vomiting, distention and constipation can indicate intestinal obstruction requiring assessment for strangulation.","source":"Clinical Medicine"},{"id":"mc-0472","title":"Appendicitis","category":"Clinical Medicine","level":"Clinical","fact":"Migratory periumbilical to right lower quadrant pain may occur but presentations vary by age and anatomy.","source":"Clinical Medicine"},{"id":"mc-0473","title":"Inflammatory bowel disease flare","category":"Clinical Medicine","level":"Clinical","fact":"Increasing bloody stool, abdominal pain and systemic symptoms warrant assessment for flare and complications.","source":"Clinical Medicine"},{"id":"mc-0474","title":"Liver decompensation","category":"Clinical Medicine","level":"Clinical","fact":"Ascites, encephalopathy, variceal bleeding or jaundice indicate complications of chronic liver disease.","source":"Clinical Medicine"},{"id":"mc-0475","title":"Hepatic encephalopathy","category":"Clinical Medicine","level":"Clinical","fact":"Altered cognition in severe liver disease may reflect multiple precipitating factors and requires exclusion of alternatives.","source":"Clinical Medicine"},{"id":"mc-0476","title":"Ischemic stroke","category":"Clinical Medicine","level":"Clinical","fact":"Sudden focal neurologic deficit requires time-sensitive stroke pathway assessment and exclusion of mimics.","source":"Clinical Medicine"},{"id":"mc-0477","title":"Transient ischemic attack","category":"Clinical Medicine","level":"Clinical","fact":"A transient focal vascular syndrome can herald stroke even when symptoms have resolved.","source":"Clinical Medicine"},{"id":"mc-0478","title":"Subarachnoid hemorrhage","category":"Clinical Medicine","level":"Clinical","fact":"Sudden thunderclap headache raises concern for subarachnoid hemorrhage even with an initially normal examination.","source":"Clinical Medicine"},{"id":"mc-0479","title":"Meningitis","category":"Clinical Medicine","level":"Clinical","fact":"Fever, headache, neck stiffness or altered consciousness require urgent infection assessment; the full triad is often absent.","source":"Clinical Medicine"},{"id":"mc-0480","title":"Status epilepticus","category":"Clinical Medicine","level":"Clinical","fact":"Prolonged or recurrent seizures without recovery constitute a neurological emergency requiring a protocol-based response.","source":"Clinical Medicine"},{"id":"mc-0481","title":"Guillain–Barré syndrome","category":"Clinical Medicine","level":"Clinical","fact":"Rapid ascending weakness with areflexia can progress to bulbar or respiratory failure.","source":"Clinical Medicine"},{"id":"mc-0482","title":"Myasthenia gravis","category":"Clinical Medicine","level":"Clinical","fact":"Fluctuating fatigable weakness, ptosis and diplopia suggest neuromuscular junction disease.","source":"Clinical Medicine"},{"id":"mc-0483","title":"Parkinson disease","category":"Clinical Medicine","level":"Clinical","fact":"Bradykinesia with rest tremor or rigidity is typical, but diagnosis remains clinical and differential-sensitive.","source":"Clinical Medicine"},{"id":"mc-0484","title":"Delirium","category":"Clinical Medicine","level":"Clinical","fact":"Acute fluctuating inattention and altered awareness usually have a physiological trigger until evaluated otherwise.","source":"Clinical Medicine"},{"id":"mc-0485","title":"Dementia syndrome","category":"Clinical Medicine","level":"Clinical","fact":"Progressive cognitive impairment affecting daily function has multiple causes and should be assessed systematically.","source":"Clinical Medicine"},{"id":"mc-0486","title":"Major depressive episode","category":"Clinical Medicine","level":"Clinical","fact":"Persistent mood change or anhedonia with functional impairment requires careful psychosocial and safety assessment.","source":"Clinical Medicine"},{"id":"mc-0487","title":"Bipolar mania","category":"Clinical Medicine","level":"Clinical","fact":"Elevated or irritable mood with reduced sleep need, increased activity and impaired judgment can signal mania.","source":"Clinical Medicine"},{"id":"mc-0488","title":"Psychosis assessment","category":"Clinical Medicine","level":"Clinical","fact":"Hallucinations or delusions require evaluation of substances, medical causes, risk and psychiatric history.","source":"Clinical Medicine"},{"id":"mc-0489","title":"Anaphylaxis","category":"Clinical Medicine","level":"Clinical","fact":"Rapid multisystem allergy involving airway, breathing or circulation is a time-critical emergency.","source":"Clinical Medicine"},{"id":"mc-0490","title":"Septic shock","category":"Clinical Medicine","level":"Clinical","fact":"Sepsis-related circulatory dysfunction may cause persistent hypotension and impaired tissue perfusion.","source":"Clinical Medicine"},{"id":"mc-0491","title":"Acute leukemia","category":"Clinical Medicine","level":"Clinical","fact":"Unexplained cytopenias, infections, bruising or blasts on film can suggest acute hematologic malignancy.","source":"Clinical Medicine"},{"id":"mc-0492","title":"Febrile neutropenia","category":"Clinical Medicine","level":"Clinical","fact":"Fever with severe neutropenia in a patient receiving myelosuppressive treatment is an urgent infection risk.","source":"Clinical Medicine"},{"id":"mc-0493","title":"Sickle cell vaso-occlusion","category":"Clinical Medicine","level":"Clinical","fact":"Severe episodic pain in sickle cell disease can coexist with infection or acute chest syndrome.","source":"Clinical Medicine"},{"id":"mc-0494","title":"Pediatric bronchiolitis","category":"Clinical Medicine","level":"Clinical","fact":"Infants may develop wheeze, crackles, feeding difficulty and hypoxemia during viral lower respiratory infection.","source":"Clinical Medicine"},{"id":"mc-0495","title":"Pediatric dehydration","category":"Clinical Medicine","level":"Clinical","fact":"Young children with fluid losses require assessment of perfusion, mental state, intake and urine output.","source":"Clinical Medicine"},{"id":"mc-0496","title":"Pediatric croup","category":"Clinical Medicine","level":"Clinical","fact":"Barking cough and inspiratory stridor suggest upper-airway inflammation, with work of breathing determining severity.","source":"Clinical Medicine"},{"id":"mc-0497","title":"Preeclampsia","category":"Clinical Medicine","level":"Clinical","fact":"New hypertension after 20 weeks with organ features can indicate preeclampsia, including without proteinuria.","source":"Clinical Medicine"},{"id":"mc-0498","title":"Ectopic pregnancy","category":"Clinical Medicine","level":"Clinical","fact":"Pregnancy with pain or bleeding may represent ectopic implantation; rupture can be life-threatening.","source":"Clinical Medicine"},{"id":"mc-0499","title":"Postpartum hemorrhage","category":"Clinical Medicine","level":"Clinical","fact":"Excessive bleeding after delivery requires immediate recognition and coordinated obstetric response.","source":"Clinical Medicine"},{"id":"mc-0500","title":"Puerperal sepsis","category":"Clinical Medicine","level":"Clinical","fact":"Postpartum fever with uterine pain or systemic illness can signal genital tract infection.","source":"Clinical Medicine"},{"id":"mc-0501","title":"Acute angle-closure glaucoma","category":"Clinical Medicine","level":"Clinical","fact":"Severe painful red eye, blurred vision, halos and nausea can indicate an ophthalmic emergency.","source":"Clinical Medicine"},{"id":"mc-0502","title":"Retinal detachment","category":"Clinical Medicine","level":"Clinical","fact":"Flashes, floaters and a curtain-like visual defect require urgent retinal evaluation.","source":"Clinical Medicine"},{"id":"mc-0503","title":"Giant cell arteritis: clinical red flags","category":"Clinical Medicine","level":"Clinical","fact":"New temporal headache with jaw claudication or visual disturbance in older adults requires urgent assessment.","source":"Clinical Medicine"},{"id":"mc-0504","title":"Septic arthritis","category":"Clinical Medicine","level":"Clinical","fact":"An acutely hot swollen painful joint with fever or risk factors needs urgent evaluation for infection.","source":"Clinical Medicine"},{"id":"mc-0505","title":"Compartment syndrome","category":"Clinical Medicine","level":"Clinical","fact":"Disproportionate pain and pain with passive stretch after injury raise concern for acute compartment syndrome.","source":"Clinical Medicine"},{"id":"mc-0506","title":"Structured history taking","category":"Clinical Skills & Procedures","level":"Clinical","fact":"A clinical history includes presenting symptoms, timeline, associated features, past conditions, medicines, allergies and relevant context.","source":"Clinical Skills & Procedures"},{"id":"mc-0507","title":"Open questions","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Begin with broad prompts and move to focused questions to avoid prematurely narrowing the differential.","source":"Clinical Skills & Procedures"},{"id":"mc-0508","title":"Pain characterization","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Characterize pain by site, onset, quality, radiation, associated features, timing and aggravating or relieving factors.","source":"Clinical Skills & Procedures"},{"id":"mc-0509","title":"Medication history","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Record medicine name, route, frequency, adherence, nonprescription products and recent changes.","source":"Clinical Skills & Procedures"},{"id":"mc-0510","title":"Allergy documentation","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Specify the suspected substance, reaction, severity, timing and whether it was verified.","source":"Clinical Skills & Procedures"},{"id":"mc-0511","title":"Social history","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Ask about living conditions, occupation, support networks, tobacco, alcohol and other relevant exposures without assumptions.","source":"Clinical Skills & Procedures"},{"id":"mc-0512","title":"Family history","category":"Clinical Skills & Procedures","level":"Clinical","fact":"A family history can highlight hereditary or shared-environment risks; relatives' age at diagnosis matters.","source":"Clinical Skills & Procedures"},{"id":"mc-0513","title":"Capacity assessment","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Decision-making capacity is decision-specific and depends on understanding, retention, weighing and communicating a choice.","source":"Clinical Skills & Procedures"},{"id":"mc-0514","title":"Informed consent","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Explain purpose, material risks, benefits and alternatives in language the patient can understand.","source":"Clinical Skills & Procedures"},{"id":"mc-0515","title":"Chaperone use","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Offer an appropriate chaperone for intimate examinations and document the patient's preferences and consent.","source":"Clinical Skills & Procedures"},{"id":"mc-0516","title":"Hand hygiene moments","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Hand hygiene is essential before patient contact, before aseptic tasks, after body-fluid risk, after patient contact and after surroundings contact.","source":"Clinical Skills & Procedures"},{"id":"mc-0517","title":"Vital signs assessment","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Temperature, pulse, respiratory rate, blood pressure, oxygen saturation and consciousness should be interpreted as a set.","source":"Clinical Skills & Procedures"},{"id":"mc-0518","title":"Respiratory rate measurement","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Count breaths without altering the patient's breathing pattern when possible; respiratory rate can signal deterioration early.","source":"Clinical Skills & Procedures"},{"id":"mc-0519","title":"Manual blood pressure","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Select an appropriate cuff size and align the arm near heart level for meaningful blood pressure measurement.","source":"Clinical Skills & Procedures"},{"id":"mc-0520","title":"Orthostatic assessment","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Postural symptoms and blood pressure changes may support orthostatic hypotension, considering medications and hydration.","source":"Clinical Skills & Procedures"},{"id":"mc-0521","title":"Capillary refill","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Capillary refill is influenced by ambient temperature and perfusion and should not stand alone as a shock marker.","source":"Clinical Skills & Procedures"},{"id":"mc-0522","title":"Glasgow Coma Scale","category":"Clinical Skills & Procedures","level":"Clinical","fact":"GCS separately scores eye opening, verbal response and motor response, with limitations in intubated patients.","source":"Clinical Skills & Procedures"},{"id":"mc-0523","title":"Pupil examination","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Compare size, shape and direct and consensual light responses as part of neurologic assessment.","source":"Clinical Skills & Procedures"},{"id":"mc-0524","title":"Fundoscopy","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Fundoscopy can reveal disc swelling or retinal disease but requires skill, equipment and clinical context.","source":"Clinical Skills & Procedures"},{"id":"mc-0525","title":"Cranial nerve screen","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Test visual fields, eye movements, facial function, hearing, palate, shoulder shrug and tongue movement as relevant.","source":"Clinical Skills & Procedures"},{"id":"mc-0526","title":"Motor examination","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Assess muscle bulk, tone, power, reflexes and coordination to localize neurologic abnormalities.","source":"Clinical Skills & Procedures"},{"id":"mc-0527","title":"Sensory examination","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Assess modalities such as light touch, pinprick, vibration and proprioception with an anatomical pattern.","source":"Clinical Skills & Procedures"},{"id":"mc-0528","title":"Cerebellar testing","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Finger-nose, heel-shin and gait testing can reveal dysmetria, ataxia or coordination impairment.","source":"Clinical Skills & Procedures"},{"id":"mc-0529","title":"Cardiovascular examination","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Inspect, palpate pulses and apex beat, then auscultate systematically and assess peripheral signs.","source":"Clinical Skills & Procedures"},{"id":"mc-0530","title":"JVP assessment","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Jugular venous pulsation can estimate right-sided filling pressure but depends on posture and technique.","source":"Clinical Skills & Procedures"},{"id":"mc-0531","title":"Murmur timing","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Identify whether a murmur is systolic or diastolic before examining location, radiation and dynamic response.","source":"Clinical Skills & Procedures"},{"id":"mc-0532","title":"Respiratory inspection","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Examine breathing rate, effort, accessory muscle use and symmetry before percussion or auscultation.","source":"Clinical Skills & Procedures"},{"id":"mc-0533","title":"Chest percussion","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Percussion may help distinguish hyperresonance, consolidation or pleural fluid, but interpretation has limits.","source":"Clinical Skills & Procedures"},{"id":"mc-0534","title":"Breath sound patterns","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Reduced air entry, bronchial breathing, crackles and wheeze represent different physical mechanisms.","source":"Clinical Skills & Procedures"},{"id":"mc-0535","title":"Abdominal examination","category":"Clinical Skills & Procedures","level":"Clinical","fact":"A systematic abdominal examination uses inspection, auscultation when appropriate, percussion and gentle palpation.","source":"Clinical Skills & Procedures"},{"id":"mc-0536","title":"Peritonism","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Guarding, rigidity and rebound tenderness suggest peritoneal irritation and require clinical context and urgent evaluation.","source":"Clinical Skills & Procedures"},{"id":"mc-0537","title":"Neurologic reflexes","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Deep tendon reflexes probe a reflex arc and descending modulation; compare sides and relevant segments.","source":"Clinical Skills & Procedures"},{"id":"mc-0538","title":"Gait analysis","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Observe stance, stride, turning and balance; distinct gait patterns can localize neurologic or musculoskeletal disease.","source":"Clinical Skills & Procedures"},{"id":"mc-0539","title":"Musculoskeletal inspection","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Compare swelling, deformity, range of motion, tenderness and neurovascular status.","source":"Clinical Skills & Procedures"},{"id":"mc-0540","title":"Diabetic foot examination","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Inspect skin and footwear, assess pulses and protective sensation, and address ulcer-risk findings.","source":"Clinical Skills & Procedures"},{"id":"mc-0541","title":"Wound assessment","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Document location, size, depth, tissue appearance, drainage, surrounding inflammation and perfusion.","source":"Clinical Skills & Procedures"},{"id":"mc-0542","title":"Aseptic non-touch technique","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Protect key parts and key sites from contamination during invasive procedures.","source":"Clinical Skills & Procedures"},{"id":"mc-0543","title":"Venepuncture","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Confirm identity, explain procedure, apply appropriate antisepsis, label specimens at bedside and safely discard sharps.","source":"Clinical Skills & Procedures"},{"id":"mc-0544","title":"Peripheral IV cannulation","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Inspect insertion site, use aseptic technique and reassess necessity, infiltration, infection or thrombophlebitis.","source":"Clinical Skills & Procedures"},{"id":"mc-0545","title":"Blood culture technique","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Obtain indicated blood cultures before antimicrobials when feasible without delaying urgent treatment.","source":"Clinical Skills & Procedures"},{"id":"mc-0546","title":"Urinary catheter decision","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Catheterization carries infection and trauma risks; use only for appropriate indications and review daily.","source":"Clinical Skills & Procedures"},{"id":"mc-0547","title":"Nasogastric tube placement","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Placement must be verified by an approved method before use, not by auscultating an air bolus.","source":"Clinical Skills & Procedures"},{"id":"mc-0548","title":"Oxygen delivery devices","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Nasal cannulae, masks and high-flow systems provide different oxygen delivery capabilities; titrate to clinical targets.","source":"Clinical Skills & Procedures"},{"id":"mc-0549","title":"Nebulizer safety","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Nebulized treatments require correct drug choice, device setup and assessment of aerosol transmission risks.","source":"Clinical Skills & Procedures"},{"id":"mc-0550","title":"ECG electrode placement","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Accurate precordial lead placement matters because misplacement can mimic cardiac pathology.","source":"Clinical Skills & Procedures"},{"id":"mc-0551","title":"Peak flow testing","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Peak expiratory flow is effort-dependent and best interpreted with personal best, technique and symptoms.","source":"Clinical Skills & Procedures"},{"id":"mc-0552","title":"Spirometry technique","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Reproducible acceptable forced maneuvers are essential to reliable obstructive or restrictive pattern assessment.","source":"Clinical Skills & Procedures"},{"id":"mc-0553","title":"Point-of-care glucose","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Capillary glucose is valuable at bedside but can be unreliable with poor perfusion or extreme hematocrit.","source":"Clinical Skills & Procedures"},{"id":"mc-0554","title":"IV fluid review","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Fluid decisions should consider indication, volume status, electrolyte composition and risk of overload.","source":"Clinical Skills & Procedures"},{"id":"mc-0555","title":"Medication administration checks","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Confirm correct patient, drug, dose, route, timing, documentation and indication according to local policy.","source":"Clinical Skills & Procedures"},{"id":"mc-0556","title":"Safe patient identification","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Use at least two approved patient identifiers rather than bed or room number for medication and specimen tasks.","source":"Clinical Skills & Procedures"},{"id":"mc-0557","title":"SBAR handover","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Situation, Background, Assessment and Recommendation provide a structured clinical communication frame.","source":"Clinical Skills & Procedures"},{"id":"mc-0558","title":"Closed-loop communication","category":"Clinical Skills & Procedures","level":"Clinical","fact":"The receiver repeats critical information and the sender confirms accuracy to reduce team errors.","source":"Clinical Skills & Procedures"},{"id":"mc-0559","title":"Surgical safety checklist","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Team verification at sign-in, time-out and sign-out helps prevent wrong-patient, wrong-site and other errors.","source":"Clinical Skills & Procedures"},{"id":"mc-0560","title":"Procedure time-out","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Pause before an invasive procedure to verify patient, procedure, site, consent and required equipment.","source":"Clinical Skills & Procedures"},{"id":"mc-0561","title":"Sharps disposal","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Dispose of needles and other sharps immediately into appropriate puncture-resistant containers without recapping.","source":"Clinical Skills & Procedures"},{"id":"mc-0562","title":"Needlestick response","category":"Clinical Skills & Procedures","level":"Clinical","fact":"After occupational exposure, provide prompt first aid, incident reporting and source/risk-based prophylaxis assessment.","source":"Clinical Skills & Procedures"},{"id":"mc-0563","title":"Sharps injury prevention","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Safety-engineered devices, training and reduced unnecessary needle use prevent avoidable exposures.","source":"Clinical Skills & Procedures"},{"id":"mc-0564","title":"Documentation","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Clinical notes should clearly separate observed findings, patient reports, assessment and plans with time and author.","source":"Clinical Skills & Procedures"},{"id":"mc-0565","title":"Discharge safety-netting","category":"Clinical Skills & Procedures","level":"Clinical","fact":"Explain expected course, red-flag symptoms, follow-up and where to seek urgent help in accessible language.","source":"Clinical Skills & Procedures"},{"id":"mc-0566","title":"ABCDE approach","category":"Emergency & Critical Care","level":"Advanced","fact":"Address airway, breathing, circulation, disability and exposure in order, treating immediate threats as found.","source":"Emergency & Critical Care"},{"id":"mc-0567","title":"Recognizing airway obstruction","category":"Emergency & Critical Care","level":"Advanced","fact":"Stridor, inability to speak, abnormal breathing and altered consciousness can indicate threatened airway.","source":"Emergency & Critical Care"},{"id":"mc-0568","title":"Basic life support","category":"Emergency & Critical Care","level":"Advanced","fact":"High-quality compressions, rapid defibrillation when indicated and minimal interruptions underpin cardiac arrest response.","source":"Emergency & Critical Care"},{"id":"mc-0569","title":"Defibrillation concept","category":"Emergency & Critical Care","level":"Advanced","fact":"Defibrillation treats selected shockable rhythms and should be integrated with the current resuscitation algorithm.","source":"Emergency & Critical Care"},{"id":"mc-0570","title":"Shock classification","category":"Emergency & Critical Care","level":"Advanced","fact":"Shock can be hypovolemic, distributive, cardiogenic or obstructive, with overlapping features.","source":"Emergency & Critical Care"},{"id":"mc-0571","title":"Hypovolemic shock","category":"Emergency & Critical Care","level":"Advanced","fact":"Reduced circulating volume decreases venous return and organ perfusion; bleeding and fluid loss are key causes.","source":"Emergency & Critical Care"},{"id":"mc-0572","title":"Cardiogenic shock","category":"Emergency & Critical Care","level":"Advanced","fact":"Pump failure can produce low cardiac output despite adequate or elevated filling pressures.","source":"Emergency & Critical Care"},{"id":"mc-0573","title":"Obstructive shock","category":"Emergency & Critical Care","level":"Advanced","fact":"Mechanical impairment of filling or outflow occurs in conditions such as tamponade or tension pneumothorax.","source":"Emergency & Critical Care"},{"id":"mc-0574","title":"Distributive shock","category":"Emergency & Critical Care","level":"Advanced","fact":"Marked vasodilation and microcirculatory dysfunction can produce maldistributed flow, as in sepsis.","source":"Emergency & Critical Care"},{"id":"mc-0575","title":"Sepsis recognition","category":"Emergency & Critical Care","level":"Advanced","fact":"Suspected infection with organ dysfunction requires prompt assessment; sepsis is not defined by fever alone.","source":"Emergency & Critical Care"},{"id":"mc-0576","title":"Sepsis source control","category":"Emergency & Critical Care","level":"Advanced","fact":"Where an infectious focus requires drainage or device removal, source control is a major part of management.","source":"Emergency & Critical Care"},{"id":"mc-0577","title":"Altered mental status","category":"Emergency & Critical Care","level":"Advanced","fact":"Immediate evaluation considers glucose, oxygenation, toxicologic, metabolic, infectious and neurologic causes.","source":"Emergency & Critical Care"},{"id":"mc-0578","title":"Acute severe headache","category":"Emergency & Critical Care","level":"Advanced","fact":"Thunderclap onset, fever, neurologic deficit or pregnancy changes the urgency and differential diagnosis.","source":"Emergency & Critical Care"},{"id":"mc-0579","title":"Status epilepticus initial priorities","category":"Emergency & Critical Care","level":"Advanced","fact":"Protect airway, assess glucose and follow a time-critical seizure protocol while seeking the cause.","source":"Emergency & Critical Care"},{"id":"mc-0580","title":"Hypoglycemia emergency","category":"Emergency & Critical Care","level":"Advanced","fact":"A patient with neuroglycopenic symptoms needs rapid bedside glucose assessment and prompt treatment by protocol.","source":"Emergency & Critical Care"},{"id":"mc-0581","title":"DKA monitoring","category":"Emergency & Critical Care","level":"Advanced","fact":"DKA management requires continuous review of fluids, potassium, glucose and acid–base status to avoid treatment complications.","source":"Emergency & Critical Care"},{"id":"mc-0582","title":"Life-threatening hyperkalemia","category":"Emergency & Critical Care","level":"Advanced","fact":"Severe hyperkalemia may cause conduction abnormalities; emergency treatment and cause correction are time-critical.","source":"Emergency & Critical Care"},{"id":"mc-0583","title":"Severe hyponatremia","category":"Emergency & Critical Care","level":"Advanced","fact":"Neurologic symptoms may reflect cerebral edema; correcting sodium too rapidly can also cause neurologic injury.","source":"Emergency & Critical Care"},{"id":"mc-0584","title":"Respiratory failure types","category":"Emergency & Critical Care","level":"Advanced","fact":"Type 1 respiratory failure is primarily hypoxemic; type 2 involves hypercapnia, often with hypoxemia.","source":"Emergency & Critical Care"},{"id":"mc-0585","title":"Noninvasive ventilation","category":"Emergency & Critical Care","level":"Advanced","fact":"NIV can support selected patients but requires monitoring of tolerance, consciousness and failure criteria.","source":"Emergency & Critical Care"},{"id":"mc-0586","title":"High-flow nasal oxygen","category":"Emergency & Critical Care","level":"Advanced","fact":"High-flow systems provide warmed humidified oxygen and some respiratory support, depending on indication.","source":"Emergency & Critical Care"},{"id":"mc-0587","title":"Intubation checklist","category":"Emergency & Critical Care","level":"Advanced","fact":"Airway preparation includes patient evaluation, personnel, equipment, physiology, medication and rescue planning.","source":"Emergency & Critical Care"},{"id":"mc-0588","title":"Post-intubation confirmation","category":"Emergency & Critical Care","level":"Advanced","fact":"Continuous waveform capnography is a key way to confirm and monitor tracheal tube placement.","source":"Emergency & Critical Care"},{"id":"mc-0589","title":"Mechanical ventilation goals","category":"Emergency & Critical Care","level":"Advanced","fact":"Ventilation balances gas exchange with avoidance of ventilator-induced lung injury.","source":"Emergency & Critical Care"},{"id":"mc-0590","title":"Ventilator associated pneumonia prevention","category":"Emergency & Critical Care","level":"Advanced","fact":"Reduce avoidable ventilator exposure and use a locally approved prevention bundle.","source":"Emergency & Critical Care"},{"id":"mc-0591","title":"Sedation assessment","category":"Emergency & Critical Care","level":"Advanced","fact":"Use consistent sedation goals and structured assessment to limit over- or under-sedation.","source":"Emergency & Critical Care"},{"id":"mc-0592","title":"Delirium in ICU","category":"Emergency & Critical Care","level":"Advanced","fact":"Critical illness delirium is common and benefits from reversible-cause assessment and nonpharmacologic prevention.","source":"Emergency & Critical Care"},{"id":"mc-0593","title":"Acute anaphylaxis priorities","category":"Emergency & Critical Care","level":"Advanced","fact":"Recognize airway, breathing and circulation involvement and follow immediate evidence-based emergency pathways.","source":"Emergency & Critical Care"},{"id":"mc-0594","title":"Massive hemorrhage","category":"Emergency & Critical Care","level":"Advanced","fact":"Major bleeding needs coordinated resuscitation and source control using locally approved transfusion pathways.","source":"Emergency & Critical Care"},{"id":"mc-0595","title":"Trauma primary survey","category":"Emergency & Critical Care","level":"Advanced","fact":"The primary survey identifies immediately life-threatening injuries before detailed secondary examination.","source":"Emergency & Critical Care"},{"id":"mc-0596","title":"Spinal injury assessment","category":"Emergency & Critical Care","level":"Advanced","fact":"Use appropriate immobilization and neurologic assessment guided by mechanism, symptoms and local trauma protocols.","source":"Emergency & Critical Care"},{"id":"mc-0597","title":"Burns first assessment","category":"Emergency & Critical Care","level":"Advanced","fact":"Estimate area, depth, mechanism, airway risk and associated injury; circumferential burns may compromise perfusion.","source":"Emergency & Critical Care"},{"id":"mc-0598","title":"Heat stroke","category":"Emergency & Critical Care","level":"Advanced","fact":"Core hyperthermia with central nervous system dysfunction requires immediate cooling and urgent supportive care.","source":"Emergency & Critical Care"},{"id":"mc-0599","title":"Hypothermia","category":"Emergency & Critical Care","level":"Advanced","fact":"Severe hypothermia changes physiology and resuscitation priorities; handle the patient gently and use tailored protocols.","source":"Emergency & Critical Care"},{"id":"mc-0600","title":"Opioid toxicity","category":"Emergency & Critical Care","level":"Advanced","fact":"Reduced respiratory rate, depressed consciousness and pinpoint pupils are suggestive but not always all present.","source":"Emergency & Critical Care"},{"id":"mc-0601","title":"Carbon monoxide poisoning","category":"Emergency & Critical Care","level":"Advanced","fact":"CO exposure can produce headache, confusion and myocardial injury; pulse oximetry may appear deceptively normal.","source":"Emergency & Critical Care"},{"id":"mc-0602","title":"Organophosphate toxicity","category":"Emergency & Critical Care","level":"Advanced","fact":"Cholinergic excess causes salivation, bronchorrhea, bradycardia and muscle weakness and requires protection from exposure.","source":"Emergency & Critical Care"},{"id":"mc-0603","title":"Snakebite envenoming","category":"Emergency & Critical Care","level":"Advanced","fact":"Species, local toxicity patterns and early systemic signs guide specialist antivenom decisions.","source":"Emergency & Critical Care"},{"id":"mc-0604","title":"Drowning injury","category":"Emergency & Critical Care","level":"Advanced","fact":"Hypoxemia from aspiration and submersion drives complications; routine prophylactic antibiotics are not automatically indicated.","source":"Emergency & Critical Care"},{"id":"mc-0605","title":"Near-fatal asthma","category":"Emergency & Critical Care","level":"Advanced","fact":"Fatigue, altered consciousness, silent chest or rising carbon dioxide can signal impending respiratory arrest.","source":"Emergency & Critical Care"},{"id":"mc-0606","title":"Toxic alcohol ingestion","category":"Emergency & Critical Care","level":"Advanced","fact":"High anion-gap acidosis or osmolar gap may suggest toxic alcohol exposure; early values can be misleading.","source":"Emergency & Critical Care"},{"id":"mc-0607","title":"Acute chest syndrome","category":"Emergency & Critical Care","level":"Advanced","fact":"Sickle cell acute chest syndrome combines respiratory symptoms with a new pulmonary infiltrate and can deteriorate rapidly.","source":"Emergency & Critical Care"},{"id":"mc-0608","title":"Neutropenic sepsis","category":"Emergency & Critical Care","level":"Advanced","fact":"Fever or clinical deterioration in significant neutropenia requires immediate recognition and protocol-led assessment.","source":"Emergency & Critical Care"},{"id":"mc-0609","title":"Obstetric eclampsia","category":"Emergency & Critical Care","level":"Advanced","fact":"Seizures in the setting of preeclampsia require urgent maternal stabilization and specialist obstetric management.","source":"Emergency & Critical Care"},{"id":"mc-0610","title":"Postpartum hemorrhage response","category":"Emergency & Critical Care","level":"Advanced","fact":"Early recognition, uterine assessment and a coordinated hemorrhage protocol are essential.","source":"Emergency & Critical Care"},{"id":"mc-0611","title":"Pediatric sepsis differences","category":"Emergency & Critical Care","level":"Advanced","fact":"Signs can be nonspecific in infants and children; assessment must use age-appropriate physiology.","source":"Emergency & Critical Care"},{"id":"mc-0612","title":"Anaphylaxis after vaccination","category":"Emergency & Critical Care","level":"Advanced","fact":"Observation and readiness to recognize and treat rare severe allergic reactions are components of safe vaccination practice.","source":"Emergency & Critical Care"},{"id":"mc-0613","title":"Medical emergency handover","category":"Emergency & Critical Care","level":"Advanced","fact":"Escalation communication should include clinical concern, measured observations, actions taken and a clear request.","source":"Emergency & Critical Care"},{"id":"mc-0614","title":"Four principles of ethics","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Autonomy, beneficence, nonmaleficence and justice are commonly used frameworks for clinical ethics.","source":"Ethics, Safety & Public Health"},{"id":"mc-0615","title":"Confidentiality","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Health information should be shared only with authorization or a valid legal and professional justification.","source":"Ethics, Safety & Public Health"},{"id":"mc-0616","title":"Privacy by design","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Health platforms should minimize identifiable data collection and apply appropriate access and retention controls.","source":"Ethics, Safety & Public Health"},{"id":"mc-0617","title":"Shared decision-making","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Present reasonable options and trade-offs while eliciting the person's values and preferences.","source":"Ethics, Safety & Public Health"},{"id":"mc-0618","title":"Health literacy","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Use plain language and teach-back to assess understanding of health information.","source":"Ethics, Safety & Public Health"},{"id":"mc-0619","title":"Cultural humility","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Ask patients about their needs and preferences rather than relying on cultural stereotypes.","source":"Ethics, Safety & Public Health"},{"id":"mc-0620","title":"Bias in clinical assessment","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Diagnostic anchoring and social biases may distort decisions; seek disconfirming evidence.","source":"Ethics, Safety & Public Health"},{"id":"mc-0621","title":"Informed refusal","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"A capable patient may decline treatment after understanding material risks and alternatives.","source":"Ethics, Safety & Public Health"},{"id":"mc-0622","title":"Duty of candour","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Open disclosure after harm or error supports patient trust and local professional obligations.","source":"Ethics, Safety & Public Health"},{"id":"mc-0623","title":"Near-miss reporting","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Reporting near misses reveals system hazards before they injure patients.","source":"Ethics, Safety & Public Health"},{"id":"mc-0624","title":"Root cause analysis","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Systems reviews investigate contributing conditions rather than assigning blame alone.","source":"Ethics, Safety & Public Health"},{"id":"mc-0625","title":"Human factors","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Workload, design, interruptions and communication affect the reliability of clinical tasks.","source":"Ethics, Safety & Public Health"},{"id":"mc-0626","title":"Safety culture","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Teams improve safety when staff can raise concerns without disproportionate punishment.","source":"Ethics, Safety & Public Health"},{"id":"mc-0627","title":"Medication error reporting","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Report adverse events and medication errors through local pharmacovigilance or safety pathways.","source":"Ethics, Safety & Public Health"},{"id":"mc-0628","title":"Diagnostic uncertainty","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Document competing hypotheses and specific follow-up plans when evidence is incomplete.","source":"Ethics, Safety & Public Health"},{"id":"mc-0629","title":"Evidence hierarchy","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Different study designs suit different questions; systematic reviews are only as strong as included evidence.","source":"Ethics, Safety & Public Health"},{"id":"mc-0630","title":"Randomized controlled trials","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Randomization reduces confounding but does not automatically solve bias or poor generalizability.","source":"Ethics, Safety & Public Health"},{"id":"mc-0631","title":"Confounding","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"A third variable associated with both exposure and outcome can distort observed associations.","source":"Ethics, Safety & Public Health"},{"id":"mc-0632","title":"Selection bias","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Selection or loss of participants can make study groups systematically noncomparable.","source":"Ethics, Safety & Public Health"},{"id":"mc-0633","title":"Information bias","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Misclassification and measurement error can distort study findings in predictable or unpredictable directions.","source":"Ethics, Safety & Public Health"},{"id":"mc-0634","title":"Absolute risk reduction","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Absolute risk reduction is the arithmetic difference in outcome risks between groups.","source":"Ethics, Safety & Public Health"},{"id":"mc-0635","title":"Relative risk","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Relative risk compares event probability between exposed and unexposed groups.","source":"Ethics, Safety & Public Health"},{"id":"mc-0636","title":"Odds ratio","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Odds ratio compares event odds and is not interchangeable with risk ratio when outcomes are common.","source":"Ethics, Safety & Public Health"},{"id":"mc-0637","title":"Number needed to treat","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"NNT is the reciprocal of absolute risk reduction over a specified time horizon.","source":"Ethics, Safety & Public Health"},{"id":"mc-0638","title":"Sensitivity","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Sensitivity is the proportion of affected people with a positive test.","source":"Ethics, Safety & Public Health"},{"id":"mc-0639","title":"Specificity","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Specificity is the proportion of unaffected people with a negative test.","source":"Ethics, Safety & Public Health"},{"id":"mc-0640","title":"Positive predictive value","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"PPV depends on disease prevalence and test sensitivity and specificity.","source":"Ethics, Safety & Public Health"},{"id":"mc-0641","title":"Likelihood ratio positive","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Positive likelihood ratio describes how strongly a positive test changes pretest odds.","source":"Ethics, Safety & Public Health"},{"id":"mc-0642","title":"Pretest probability","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Interpret diagnostic tests according to probability estimated before testing, not as isolated yes/no answers.","source":"Ethics, Safety & Public Health"},{"id":"mc-0643","title":"Screening versus diagnosis","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Screening tests assess asymptomatic populations, whereas diagnostic tests investigate a clinical concern.","source":"Ethics, Safety & Public Health"},{"id":"mc-0644","title":"Lead-time bias","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Earlier detection can increase apparent survival time without delaying the actual time of death.","source":"Ethics, Safety & Public Health"},{"id":"mc-0645","title":"Length-time bias","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Screening preferentially detects slower-growing disease and can distort apparent benefits.","source":"Ethics, Safety & Public Health"},{"id":"mc-0646","title":"Overdiagnosis","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Screening may detect abnormalities that would never have caused symptoms or harm.","source":"Ethics, Safety & Public Health"},{"id":"mc-0647","title":"Primary prevention","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Primary prevention aims to avoid disease onset through measures such as immunization or exposure reduction.","source":"Ethics, Safety & Public Health"},{"id":"mc-0648","title":"Secondary prevention","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Secondary prevention identifies disease earlier to reduce progression or harm.","source":"Ethics, Safety & Public Health"},{"id":"mc-0649","title":"Tertiary prevention","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Tertiary prevention limits disability and complications from established disease.","source":"Ethics, Safety & Public Health"},{"id":"mc-0650","title":"Incidence","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Incidence counts new cases arising within a defined population over a period.","source":"Ethics, Safety & Public Health"},{"id":"mc-0651","title":"Prevalence","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Prevalence represents existing cases at a point or during a period.","source":"Ethics, Safety & Public Health"},{"id":"mc-0652","title":"Case fatality ratio","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Case fatality describes deaths among recognized cases over a specified interval.","source":"Ethics, Safety & Public Health"},{"id":"mc-0653","title":"Epidemic curve","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"A time plot of case onset can support outbreak characterization and exposure hypotheses.","source":"Ethics, Safety & Public Health"},{"id":"mc-0654","title":"Contact tracing","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Contact tracing identifies exposed persons to guide testing, prevention and public-health action.","source":"Ethics, Safety & Public Health"},{"id":"mc-0655","title":"Vaccination schedule","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"National schedules vary by age, product and epidemiology; consult current local program guidance.","source":"Ethics, Safety & Public Health"},{"id":"mc-0656","title":"Cold chain","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Temperature-sensitive vaccines require monitored storage and transport according to product specifications.","source":"Ethics, Safety & Public Health"},{"id":"mc-0657","title":"Antimicrobial resistance","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Selection pressure, transmission and inadequate infection prevention contribute to antimicrobial resistance.","source":"Ethics, Safety & Public Health"},{"id":"mc-0658","title":"One Health","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"One Health integrates human, animal and environmental health to address shared threats.","source":"Ethics, Safety & Public Health"},{"id":"mc-0659","title":"WASH","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Water, sanitation and hygiene reduce transmission of many enteric and other infectious diseases.","source":"Ethics, Safety & Public Health"},{"id":"mc-0660","title":"Air pollution","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Fine particulate exposure contributes to respiratory and cardiovascular disease burden.","source":"Ethics, Safety & Public Health"},{"id":"mc-0661","title":"Occupational exposure","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Workplace assessment should consider chemicals, biological hazards, noise, repetitive strain and psychosocial factors.","source":"Ethics, Safety & Public Health"},{"id":"mc-0662","title":"Tobacco cessation","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Behavioral support and evidence-based therapies can improve smoking-cessation success.","source":"Ethics, Safety & Public Health"},{"id":"mc-0663","title":"Alcohol screening","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Validated screening tools identify risky drinking and support brief interventions and referral.","source":"Ethics, Safety & Public Health"},{"id":"mc-0664","title":"Nutrition screening","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Nutrition risk requires assessment of intake, weight change, functional status and disease burden.","source":"Ethics, Safety & Public Health"},{"id":"mc-0665","title":"Health inequity","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Unequal exposure, access and structural conditions can produce preventable differences in health outcomes.","source":"Ethics, Safety & Public Health"},{"id":"mc-0666","title":"Disability accessibility","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Clinical information and services should be adapted to sensory, cognitive, mobility and communication needs.","source":"Ethics, Safety & Public Health"},{"id":"mc-0667","title":"Telemedicine safety","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Remote care requires patient identification, consent, privacy and a plan for urgent in-person escalation.","source":"Ethics, Safety & Public Health"},{"id":"mc-0668","title":"Handover accountability","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"A safe handover confirms who owns pending tests, treatment actions and follow-up responsibilities.","source":"Ethics, Safety & Public Health"},{"id":"mc-0669","title":"Research ethics","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Human research requires appropriate consent, independent review and safeguards for vulnerable participants.","source":"Ethics, Safety & Public Health"},{"id":"mc-0670","title":"Data anonymization limits","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Removing direct identifiers does not guarantee that a patient record cannot be reidentified.","source":"Ethics, Safety & Public Health"},{"id":"mc-0671","title":"Public health surveillance","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Surveillance systematically collects and analyzes data to guide prevention and response.","source":"Ethics, Safety & Public Health"},{"id":"mc-0672","title":"Disaster triage principles","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Mass-casualty triage allocates limited resources using an approved incident-specific system.","source":"Ethics, Safety & Public Health"},{"id":"mc-0673","title":"Planetary health","category":"Ethics, Safety & Public Health","level":"Foundation","fact":"Human health depends on environmental systems including climate, biodiversity, food and water security.","source":"Ethics, Safety & Public Health"}]};